-- Skema SIMRS Khanza untuk PostgreSQL 9.5
-- Dihasilkan otomatis dari SIMRS-Khanza/sik.sql oleh konversi-khanza-pg95.js.
-- Isi: tabel, primary key, foreign key, unique, check (dari enum), dan index.
-- Tidak berisi data, trigger, stored procedure, function, atau view.
-- Lihat khanza-pg95-laporan.txt untuk daftar perubahan dan item yang dilewati.

BEGIN;
CREATE SCHEMA khanza;
SET search_path TO khanza;

-- Tabel admin
CREATE TABLE "admin" (
  "usere" text,
  "passworde" text
);

-- Tabel admisi_skoring_tolac
CREATE TABLE "admisi_skoring_tolac" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp,
  "his_frekuensi" varchar(2),
  "his_durasi_detik" varchar(5),
  "djj" varchar(5),
  "pembukaan_cm" varchar(2),
  "pendataran_persen" varchar(3),
  "penurunan_kepala" varchar(20),
  "pilihan_usia" varchar(11) CHECK ("pilihan_usia" IN ('< 40 Tahun', '>= 40 Tahun')),
  "skor_usia" varchar(1),
  "pilihan_riwayat_pervaginam" varchar(20) CHECK ("pilihan_riwayat_pervaginam" IN ('Sebelum & Sesudah SC', 'Sesudah SC Saja', 'Sebelum SC Saja', 'Tidak Pernah')),
  "skor_riwayat_pervaginam" varchar(1),
  "pilihan_indikasi_sc" varchar(44) CHECK ("pilihan_indikasi_sc" IN ('Bukan Kegagalan Kemajuan Persalinan', 'Kegagalan Kemajuan Persalinan / CPD-distosia')),
  "skor_indikasi_sc" varchar(1),
  "pilihan_pendataran" varchar(6) CHECK ("pilihan_pendataran" IN ('>75%', '25–75%', '<25%')),
  "skor_pendataran" varchar(1),
  "pilihan_pembukaan" varchar(6) CHECK ("pilihan_pembukaan" IN ('>=4 cm', '<4 cm')),
  "skor_pembukaan" varchar(1),
  "total_skor" varchar(2),
  "peluang_vbac" varchar(6) NOT NULL,
  "keputusan" varchar(12) CHECK ("keputusan" IN ('Lanjut TOLAC', 'Lakukan SC')),
  "keterangan" varchar(100),
  "kd_dokter" varchar(15),
  CONSTRAINT "admisi_skoring_tolac_pkey" PRIMARY KEY ("no_rawat")
);

