  "no_rawat" varchar(17),
  "tglsep" date,
  "tglrujukan" date,
  "no_rujukan" varchar(40),
  "kdppkrujukan" varchar(12),
  "nmppkrujukan" varchar(200),
  "kdppkpelayanan" varchar(12),
  "nmppkpelayanan" varchar(200),
  "jnspelayanan" varchar(1) CHECK ("jnspelayanan" IN ('1', '2')),
  "catatan" varchar(100),
  "diagawal" varchar(10),
  "nmdiagnosaawal" varchar(400),
  "kdpolitujuan" varchar(15),
  "nmpolitujuan" varchar(50),
  "klsrawat" varchar(1) CHECK ("klsrawat" IN ('1', '2', '3')),
  "klsnaik" varchar(1) NOT NULL CHECK ("klsnaik" IN ('', '1', '2', '3', '4', '5', '6', '7', '8')),
  "pembiayaan" varchar(1) NOT NULL CHECK ("pembiayaan" IN ('', '1', '2', '3')),
