  "sesaknapasaktivitas" varchar(8) NOT NULL CHECK ("sesaknapasaktivitas" IN ('', '0. Tidak', '1. Ya')),
  "nyeridadaaktivitas" varchar(8) NOT NULL CHECK ("nyeridadaaktivitas" IN ('', '0. Tidak', '1. Ya')),
  "terkontrol" varchar(8) NOT NULL CHECK ("terkontrol" IN ('', '0. Tidak', '1. Ya')),
  "gejala2xminggu" varchar(8) NOT NULL CHECK ("gejala2xminggu" IN ('', '0. Tidak', '1. Ya')),
  "bangunmalam" varchar(8) NOT NULL CHECK ("bangunmalam" IN ('', '0. Tidak', '1. Ya')),
  "keterbatasanfisik" varchar(8) NOT NULL CHECK ("keterbatasanfisik" IN ('', '0. Tidak', '1. Ya')),
  "fungsiparu" varchar(5) NOT NULL,
