  "epileptik6bulan" varchar(8) NOT NULL CHECK ("epileptik6bulan" IN ('', '0. Tidak', '1. Ya')),
  "efeksampingoab" varchar(8) NOT NULL CHECK ("efeksampingoab" IN ('', '0. Tidak', '1. Ya')),
  "hamilmenyusui" varchar(8) NOT NULL CHECK ("hamilmenyusui" IN ('', '0. Tidak', '1. Ya')),
  "remisi" varchar(5) NOT NULL,
  "terapirumatan" varchar(8) NOT NULL CHECK ("terapirumatan" IN ('', '0. Tidak', '1. Ya')),
  "usia" varchar(5) NOT NULL,
