-- Tabel catatan_anestesi_sedasi
CREATE TABLE "catatan_anestesi_sedasi" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "kd_dokter_bedah" varchar(20) NOT NULL,
  "kd_dokter_anestesi" varchar(20) NOT NULL,
  "diagnosa_pre_bedah" varchar(50) NOT NULL,
  "tindakan_jenis_pembedahan" varchar(50) NOT NULL,
  "diagnosa_pasca_bedah" varchar(50) NOT NULL,
  "pre_induksi_jam" varchar(10),
  "pre_induksi_kesadaran" varchar(13) CHECK ("pre_induksi_kesadaran" IN ('Compos Mentis', 'Somnolence', 'Sopor', 'Coma', 'Alert', 'Confusion', 'Voice', 'Pain', 'Unresponsive', 'Apatis', 'Delirium')),
  "pre_induksi_td" varchar(8),
  "pre_induksi_nadi" varchar(5),
  "pre_induksi_rr" varchar(5),
  "pre_induksi_suhu" varchar(5),
  "pre_induksi_o2" varchar(5),
  "pre_induksi_tb" varchar(5),
  "pre_induksi_bb" varchar(5),
  "pre_induksi_rhesus" varchar(1) CHECK ("pre_induksi_rhesus" IN ('+', '-')),
  "pre_induksi_hb" varchar(5),
  "pre_induksi_ht" varchar(5),
  "pre_induksi_leko" varchar(5),
  "pre_induksi_trombo" varchar(5),
  "pre_induksi_btct" varchar(5),
  "pre_induksi_gds" varchar(5),
  "pre_induksi_lainlain" varchar(30),
  "teknik_alat_hiopotensi" varchar(5) CHECK ("teknik_alat_hiopotensi" IN ('Ya', 'Tidak')),
  "teknik_alat_tci" varchar(5) CHECK ("teknik_alat_tci" IN ('Ya', 'Tidak')),
  "teknik_alat_cpb" varchar(5) CHECK ("teknik_alat_cpb" IN ('Ya', 'Tidak')),
  "teknik_alat_ventilasi" varchar(5) CHECK ("teknik_alat_ventilasi" IN ('Ya', 'Tidak')),
  "teknik_alat_broncoskopy" varchar(5) CHECK ("teknik_alat_broncoskopy" IN ('Ya', 'Tidak')),
  "teknik_alat_glidescopi" varchar(5) CHECK ("teknik_alat_glidescopi" IN ('Ya', 'Tidak')),
  "teknik_alat_usg" varchar(5) CHECK ("teknik_alat_usg" IN ('Ya', 'Tidak')),
  "teknik_alat_stimulator_saraf" varchar(5) CHECK ("teknik_alat_stimulator_saraf" IN ('Ya', 'Tidak')),
  "teknik_alat_lainlain" varchar(100),
  "monitoring_ekg" varchar(5) CHECK ("monitoring_ekg" IN ('Ya', 'Tidak')),
  "monitoring_ekg_keterangan" varchar(50),
  "monitoring_arteri" varchar(5) CHECK ("monitoring_arteri" IN ('Ya', 'Tidak')),
  "monitoring_arteri_keterangan" varchar(50),
  "monitoring_cvp" varchar(5) CHECK ("monitoring_cvp" IN ('Ya', 'Tidak')),
  "monitoring_cvp_keterangan" varchar(50),
  "monitoring_etco" varchar(5) CHECK ("monitoring_etco" IN ('Ya', 'Tidak')),
  "monitoring_stetoskop" varchar(5) CHECK ("monitoring_stetoskop" IN ('Ya', 'Tidak')),
  "monitoring_nibp" varchar(5) CHECK ("monitoring_nibp" IN ('Ya', 'Tidak')),
  "monitoring_ngt" varchar(5) CHECK ("monitoring_ngt" IN ('Ya', 'Tidak')),
  "monitoring_bis" varchar(5) CHECK ("monitoring_bis" IN ('Ya', 'Tidak')),
  "monitoring_cath_a_pulmo" varchar(5) CHECK ("monitoring_cath_a_pulmo" IN ('Ya', 'Tidak')),
  "monitoring_spo2" varchar(5) CHECK ("monitoring_spo2" IN ('Ya', 'Tidak')),
  "monitoring_kateter" varchar(5) CHECK ("monitoring_kateter" IN ('Ya', 'Tidak')),
  "monitoring_temp" varchar(5) CHECK ("monitoring_temp" IN ('Ya', 'Tidak')),
  "monitoring_lainlain" varchar(100),
  "status_fisik_asa" varchar(1) CHECK ("status_fisik_asa" IN ('1', '2', '3', '4', '5', 'E')),
  "status_fisik_alergi" varchar(5) NOT NULL CHECK ("status_fisik_alergi" IN ('Tidak', 'Ya')),
  "status_fisik_alergi_keterangan" varchar(50),
  "status_fisik_penyulit_sedasi" varchar(150),
  "perencanaan_lanjut" varchar(5) CHECK ("perencanaan_lanjut" IN ('Ya', 'Tidak')),
  "perencanaan_lanjut_sedasi" varchar(9) CHECK ("perencanaan_lanjut_sedasi" IN ('Sedang', 'Dalam', 'Tidak', 'Lain-lain')),
  "perencanaan_lanjut_sedasi_keterangan" varchar(30),
  "perencanaan_lanjut_spinal" varchar(5) CHECK ("perencanaan_lanjut_spinal" IN ('Ya', 'Tidak')),
  "perencanaan_lanjut_anestesi_umum" varchar(5) CHECK ("perencanaan_lanjut_anestesi_umum" IN ('Ya', 'Tidak')),
  "perencanaan_lanjut_anestesi_umum_keterangan" varchar(30),
  "perencanaan_lanjut_blok_perifer" varchar(5) CHECK ("perencanaan_lanjut_blok_perifer" IN ('Ya', 'Tidak')),
  "perencanaan_lanjut_blok_perifer_keterangan" varchar(30),
  "perencanaan_lanjut_epidural" varchar(5) CHECK ("perencanaan_lanjut_epidural" IN ('Ya', 'Tidak')),
  "perencanaan_batal" varchar(5) CHECK ("perencanaan_batal" IN ('Ya', 'Tidak')),
  "perencanaan_batal_alasan" varchar(150),
  "nip_perawat_ok" varchar(20),
  "nip_perawat_anestesi" varchar(20),
  CONSTRAINT "catatan_anestesi_sedasi_pkey" PRIMARY KEY ("no_rawat", "tanggal")
);

