  "penandaan_area_operasi" varchar(16) CHECK ("penandaan_area_operasi" IN ('Ada', 'Tidak Ada', 'Tidak Diperlukan')),
  "keadaan_umum" varchar(6) CHECK ("keadaan_umum" IN ('Baik', 'Sedang', 'Lemah')),
  "pemeriksaan_penunjang_rontgen" varchar(16) CHECK ("pemeriksaan_penunjang_rontgen" IN ('Ada', 'Tidak Ada', 'Tidak Diperlukan')),
  "keterangan_pemeriksaan_penunjang_rontgen" varchar(20),
  "pemeriksaan_penunjang_ekg" varchar(16) CHECK ("pemeriksaan_penunjang_ekg" IN ('Ada', 'Tidak Ada', 'Tidak Diperlukan')),
  "keterangan_pemeriksaan_penunjang_ekg" varchar(20),
  "pemeriksaan_penunjang_usg" varchar(16) CHECK ("pemeriksaan_penunjang_usg" IN ('Ada', 'Tidak Ada', 'Tidak Diperlukan')),
  "keterangan_pemeriksaan_penunjang_usg" varchar(20),
  "pemeriksaan_penunjang_ctscan" varchar(16) CHECK ("pemeriksaan_penunjang_ctscan" IN ('Ada', 'Tidak Ada', 'Tidak Diperlukan')),
  "keterangan_pemeriksaan_penunjang_ctscan" varchar(20),
  "pemeriksaan_penunjang_mri" varchar(16) CHECK ("pemeriksaan_penunjang_mri" IN ('Ada', 'Tidak Ada', 'Tidak Diperlukan')),
  "keterangan_pemeriksaan_penunjang_mri" varchar(20),
  "persiapan_darah" varchar(16) CHECK ("persiapan_darah" IN ('Ada', 'Tidak Ada', 'Tidak Diperlukan')),
