);

-- Tabel dokter
CREATE TABLE "dokter" (
  "kd_dokter" varchar(20) NOT NULL,
  "nm_dokter" varchar(50),
  "jk" varchar(1) CHECK ("jk" IN ('L', 'P')),
  "tmp_lahir" varchar(20),
  "tgl_lahir" date,
  "gol_drh" varchar(2) CHECK ("gol_drh" IN ('A', 'B', 'O', 'AB', '-')),
  "agama" varchar(12),
  "almt_tgl" varchar(60),
  "no_telp" varchar(13),
  "email" varchar(70) NOT NULL,
  "stts_nikah" varchar(13) CHECK ("stts_nikah" IN ('BELUM MENIKAH', 'MENIKAH', 'JANDA', 'DUDHA', 'JOMBLO')),
  "kd_sps" varchar(5),
  "alumni" varchar(60),
  "no_ijn_praktek" varchar(120),
  "status" varchar(1) NOT NULL CHECK ("status" IN ('0', '1')),
  CONSTRAINT "dokter_pkey" PRIMARY KEY ("kd_dokter")
);

