-- Tabel edukasi_pasien_keluarga_rj
CREATE TABLE "edukasi_pasien_keluarga_rj" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "nip" varchar(20) NOT NULL,
  "bicara" varchar(15) CHECK ("bicara" IN ('Normal', 'Gangguan Bicara')),
  "keterangan_bicara" varchar(50),
  "bahasa_sehari" varchar(50),
  "perlu_penerjemah" varchar(5) CHECK ("perlu_penerjemah" IN ('Ya', 'Tidak')),
  "keterangan_penerjemah" varchar(50),
  "bahasa_isyarat" varchar(5) CHECK ("bahasa_isyarat" IN ('Ya', 'Tidak')),
  "cara_belajar" varchar(19) CHECK ("cara_belajar" IN ('Menulis', 'Audio-Visual/Gambar', 'Diskusi', 'Simulasi')),
  "hambatan_belajar" varchar(18) CHECK ("hambatan_belajar" IN ('Tidak Ada', 'Takut/Gelisah', 'Tidak Tertarik', 'Nyeri Tidak Nyaman', 'Buta Huruf', 'Gangguan Kognitif', 'Lain-lain')),
  "keterangan_hambatan_belajar" varchar(50),
  "kemampuan_belajar" varchar(30) CHECK ("kemampuan_belajar" IN ('Mampu Menerima Informasi', 'Tidak Mampu Menerima Informasi')),
  "keterangan_kemampuan_belajar" varchar(50),
  "penyakitnya_merupakan" varchar(12) NOT NULL CHECK ("penyakitnya_merupakan" IN ('Ujian/Cobaan', 'Kutukan', 'Lain-lain')),
  "keterangan_penyakitnya_merupakan" varchar(50) NOT NULL,
  "keputusan_memilih_layanan" varchar(9) NOT NULL CHECK ("keputusan_memilih_layanan" IN ('Sendiri', 'Keluarga', 'Lain-lain')),
  "keterangan_keputusan_memilih_layanan" varchar(50) NOT NULL,
  "keyakinan_terhadap_terapi" varchar(36) NOT NULL CHECK ("keyakinan_terhadap_terapi" IN ('Pasrah', 'Yakin Sembuh Jika Kontrol Teratur', 'Yakin Sembuh Jika Minum Obat Teratur', 'Lain-lain')),
  "keterangan_keyakinan_terhadap_terapi" varchar(50) NOT NULL,
  "aspek_keyakinan_dipertimbangkan" varchar(5) NOT NULL CHECK ("aspek_keyakinan_dipertimbangkan" IN ('Ada', 'Tidak')),
  "keterangan_aspek_keyakinan_dipertimbangkan" varchar(50) NOT NULL,
  "kesediaan_menerima_informasi" varchar(5) NOT NULL CHECK ("kesediaan_menerima_informasi" IN ('Ya', 'Tidak')),
  "topik_edukasi_penyakit" varchar(5) NOT NULL CHECK ("topik_edukasi_penyakit" IN ('Ya', 'Tidak')),
  "topik_edukasi_rencana_tindakan" varchar(5) NOT NULL CHECK ("topik_edukasi_rencana_tindakan" IN ('Ya', 'Tidak')),
  "topik_edukasi_pengobatan" varchar(5) NOT NULL CHECK ("topik_edukasi_pengobatan" IN ('Ya', 'Tidak')),
  "topik_edukasi_hasil_layanan" varchar(5) NOT NULL CHECK ("topik_edukasi_hasil_layanan" IN ('Ya', 'Tidak')),
  CONSTRAINT "edukasi_pasien_keluarga_rj_pkey" PRIMARY KEY ("no_rawat")
);

