-- Tabel hasil_endoskopi_hidung
CREATE TABLE "hasil_endoskopi_hidung" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "kd_dokter" varchar(20) NOT NULL,
  "diagnosa_klinis" varchar(50) NOT NULL,
  "kiriman_dari" varchar(50) NOT NULL,
  "kondisi_hidung_kanan" varchar(12) CHECK ("kondisi_hidung_kanan" IN ('Lapang', 'Sempit', 'Mukosa Edema')),
  "kondisi_hidung_kiri" varchar(12) CHECK ("kondisi_hidung_kiri" IN ('Lapang', 'Sempit', 'Mukosa Edema')),
  "kavum_nasi_kanan" varchar(16) CHECK ("kavum_nasi_kanan" IN ('Mukosa Pucat', 'Mukosa Hiperemis', 'Massa', 'Polip')),
  "kavum_nasi_kiri" varchar(16) CHECK ("kavum_nasi_kiri" IN ('Mukosa Pucat', 'Mukosa Hiperemis', 'Massa', 'Polip')),
  "konka_inferior_kanan" varchar(10) CHECK ("konka_inferior_kanan" IN ('Eutrofi', 'Hipertrofi', 'Atrofi')),
  "konka_inferior_kiri" varchar(10) CHECK ("konka_inferior_kiri" IN ('Eutrofi', 'Hipertrofi', 'Atrofi')),
  "meatus_medius_kanan" varchar(12) CHECK ("meatus_medius_kanan" IN ('Terbuka', 'Tertutup', 'Mukosa Edema', 'Polip', 'Sekret')),
  "meatus_medius_kiri" varchar(12) CHECK ("meatus_medius_kiri" IN ('Terbuka', 'Tertutup', 'Mukosa Edema', 'Polip', 'Sekret')),
  "septum_kanan" varchar(7) CHECK ("septum_kanan" IN ('Lurus', 'Deviasi', 'Spina')),
  "septum_kiri" varchar(7) CHECK ("septum_kiri" IN ('Lurus', 'Deviasi', 'Spina')),
  "nasofaring_kanan" varchar(10) CHECK ("nasofaring_kanan" IN ('Normal', 'Adenoid', 'Keradangan', 'Massa')),
  "nasofaring_kiri" varchar(10) CHECK ("nasofaring_kiri" IN ('Normal', 'Adenoid', 'Keradangan', 'Massa')),
  "lainlain_kanan" varchar(100),
  "lainlain_kiri" varchar(100),
  "kesimpulan" varchar(300),
  CONSTRAINT "hasil_endoskopi_hidung_pkey" PRIMARY KEY ("no_rawat")
);

-- Tabel hasil_endoskopi_hidung_gambar
