  "no_rawat" varchar(20) NOT NULL,
  "photo" varchar(500),
  CONSTRAINT "hasil_endoskopi_hidung_gambar_pkey" PRIMARY KEY ("no_rawat")
);

-- Tabel hasil_endoskopi_telinga
CREATE TABLE "hasil_endoskopi_telinga" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "kd_dokter" varchar(20) NOT NULL,
  "diagnosa_klinis" varchar(50) NOT NULL,
  "kiriman_dari" varchar(50) NOT NULL,
  "bentuk_liang_telinga_kanan" varchar(9) CHECK ("bentuk_liang_telinga_kanan" IN ('Lapang', 'Sempit', 'Destruksi')),
  "bentuk_liang_telinga_kiri" varchar(9) CHECK ("bentuk_liang_telinga_kiri" IN ('Lapang', 'Sempit', 'Destruksi')),
  "kondisi_liang_telinga_kanan" varchar(14) CHECK ("kondisi_liang_telinga_kanan" IN ('Serumen', 'Sekret', 'Jamur', 'Kolesteatoma', 'Massa/Jaringan', 'Benda Asing', 'Lainnya')),
  "keterangan_kondisi_liang_telinga_kanan" varchar(30),
  "kondisi_liang_telinga_kiri" varchar(14) CHECK ("kondisi_liang_telinga_kiri" IN ('Serumen', 'Sekret', 'Jamur', 'Kolesteatoma', 'Massa/Jaringan', 'Benda Asing', 'Lainnya')),
  "keterangan_kondisi_liang_telinga_kiri" varchar(30),
  "membran_timpani_intak_kanan" varchar(9) CHECK ("membran_timpani_intak_kanan" IN ('Normal', 'Hiperemis', 'Bulging', 'Retraksi', 'Sklerotik')),
  "membran_timpani_intak_kiri" varchar(9) CHECK ("membran_timpani_intak_kiri" IN ('Normal', 'Hiperemis', 'Bulging', 'Retraksi', 'Sklerotik')),
  "membran_timpani_perforasi_kanan" varchar(8) CHECK ("membran_timpani_perforasi_kanan" IN ('Sentral', 'Atik', 'Marginal', 'Lainnya')),
  "keterangan_membran_timpani_perforasi_kanan" varchar(30),
  "membran_timpani_perforasi_kiri" varchar(8) CHECK ("membran_timpani_perforasi_kiri" IN ('Sentral', 'Atik', 'Marginal', 'Lainnya')),
  "keterangan_membran_timpani_perforasi_kiri" varchar(30),
  "kavum_timpani_mukosa_kanan" varchar(40),
  "kavum_timpani_mukosa_kiri" varchar(40),
  "kavum_timpani_osikel_kanan" varchar(40),
  "kavum_timpani_osikel_kiri" varchar(40),
  "kavum_timpani_isthmus_kanan" varchar(40),
  "kavum_timpani_isthmus_kiri" varchar(40),
  "kavum_timpani_anterior_kanan" varchar(40),
  "kavum_timpani_anterior_kiri" varchar(40),
  "kavum_timpani_posterior_kanan" varchar(40),
  "kavum_timpani_posterior_kiri" varchar(40),
  "lainlain_kanan" varchar(100),
  "lainlain_kiri" varchar(100),
  "kesimpulan" varchar(300),
  "anjuran" varchar(300),
  CONSTRAINT "hasil_endoskopi_telinga_pkey" PRIMARY KEY ("no_rawat")
);

