-- Tabel hasil_persalinan_tolac
CREATE TABLE "hasil_persalinan_tolac" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "awitan_persalinan" varchar(7) CHECK ("awitan_persalinan" IN ('Spontan', 'Induksi')),
  "augmentasi" varchar(5) CHECK ("augmentasi" IN ('Tidak', 'Ya')),
  "ctg_kontinu" varchar(5) CHECK ("ctg_kontinu" IN ('Ya', 'Tidak')),
  "cara_persalinan" varchar(22) CHECK ("cara_persalinan" IN ('VBAC Berhasil', 'Gagal TOLAC - SC Ulang')),
  "indikasi_gagal" varchar(255),
  "lama_kala2_menit" varchar(3),
  "ruptur_uteri" varchar(14) CHECK ("ruptur_uteri" IN ('Tidak Ada', 'Dehisensi', 'Ruptur Komplit')),
  "jumlah_perdarahan_ml" varchar(5),
  "transfusi" varchar(5) CHECK ("transfusi" IN ('Tidak', 'Ya')),
  "histerektomi" varchar(5) CHECK ("histerektomi" IN ('Tidak', 'Ya')),
  "komplikasi_lain" varchar(255),
  "luaran_perinatal" varchar(18) CHECK ("luaran_perinatal" IN ('Hidup', 'Lahir Mati', 'Meninggal Neonatal')),
  "bb_lahir_gram" varchar(4),
  "apgar_1" varchar(2),
  "apgar_5" varchar(2),
  "hie" varchar(5) CHECK ("hie" IN ('Tidak', 'Ya')),
  "masuk_nicu" varchar(5) CHECK ("masuk_nicu" IN ('Tidak', 'Ya')),
  "keterangan" varchar(200),
  "kd_dokter" varchar(20) NOT NULL,
  CONSTRAINT "hasil_persalinan_tolac_pkey" PRIMARY KEY ("no_rawat")
);

