  "no_faktur" varchar(15) NOT NULL,
  "kode_suplier" varchar(5) NOT NULL,
  "nip" varchar(20) NOT NULL,
  "tgl_beli" date NOT NULL,
  "subtotal" double precision NOT NULL,
  "potongan" double precision NOT NULL,
  "total" double precision NOT NULL,
  "ppn" double precision,
  "meterai" double precision,
  "tagihan" double precision,
  "kd_rek" varchar(15),
  "kd_rek_aset" varchar(15) NOT NULL,
  CONSTRAINT "inventaris_pembelian_pkey" PRIMARY KEY ("no_faktur")
);

-- Tabel inventaris_pemesanan
CREATE TABLE "inventaris_pemesanan" (
  "no_faktur" varchar(20) NOT NULL,
  "no_order" varchar(20) NOT NULL,
  "kode_suplier" varchar(5),
  "nip" varchar(20),
  "tgl_pesan" date,
  "tgl_faktur" date,
  "tgl_tempo" date,
  "total1" double precision NOT NULL,
  "potongan" double precision NOT NULL,
  "total2" double precision NOT NULL,
  "ppn" double precision NOT NULL,
  "meterai" double precision,
  "tagihan" double precision NOT NULL,
  "status" varchar(13) CHECK ("status" IN ('Sudah Dibayar', 'Belum Dibayar', 'Belum Lunas', 'Titip Faktur')),
  "kd_rek_aset" varchar(15) NOT NULL,
  CONSTRAINT "inventaris_pemesanan_pkey" PRIMARY KEY ("no_faktur")
);

-- Tabel inventaris_peminjaman
CREATE TABLE "inventaris_peminjaman" (
  "peminjam" varchar(50) DEFAULT '' NOT NULL,
  "tlp" varchar(13) NOT NULL,
  "no_inventaris" varchar(30) DEFAULT '' NOT NULL,
  "tgl_pinjam" date NOT NULL,
  "tgl_kembali" date,
  "nip" varchar(20) DEFAULT '' NOT NULL,
  "status_pinjam" varchar(14) CHECK ("status_pinjam" IN ('Masih Dipinjam', 'Sudah Kembali')),
  CONSTRAINT "inventaris_peminjaman_pkey" PRIMARY KEY ("peminjam", "no_inventaris", "tgl_pinjam", "nip")
);

-- Tabel inventaris_produsen
CREATE TABLE "inventaris_produsen" (
  "kode_produsen" varchar(10) NOT NULL,
  "nama_produsen" varchar(40),
  "alamat_produsen" varchar(70),
  "no_telp" varchar(13),
  "email" varchar(25),
  "website_produsen" varchar(30),
  CONSTRAINT "inventaris_produsen_pkey" PRIMARY KEY ("kode_produsen")
);

-- Tabel inventaris_ruang
CREATE TABLE "inventaris_ruang" (
  "id_ruang" varchar(5) NOT NULL,
  "nama_ruang" varchar(40) NOT NULL,
  CONSTRAINT "inventaris_ruang_pkey" PRIMARY KEY ("id_ruang")
);

-- Tabel inventaris_sterilisasi_cssd
CREATE TABLE "inventaris_sterilisasi_cssd" (
  "keterangan_strerilisasi" varchar(80) NOT NULL,
  "no_sirkulasi" varchar(20) NOT NULL,
  "tgl_sterilisasi" timestamp,
  "nip" varchar(20) DEFAULT '' NOT NULL,
  CONSTRAINT "inventaris_sterilisasi_cssd_pkey" PRIMARY KEY ("no_sirkulasi")
);

-- Tabel inventaris_suplier
CREATE TABLE "inventaris_suplier" (
  "kode_suplier" varchar(5) NOT NULL,
  "nama_suplier" varchar(50),
  "alamat" varchar(50),
  "kota" varchar(20),
  "no_telp" varchar(13),
  "nama_bank" varchar(30),
  "rekening" varchar(20),
  CONSTRAINT "inventaris_suplier_pkey" PRIMARY KEY ("kode_suplier")
);

-- Tabel inventaris_titip_faktur
CREATE TABLE "inventaris_titip_faktur" (
  "no_tagihan" varchar(20) NOT NULL,
  "tanggal" date,
  "nip" varchar(20),
  "keterangan" varchar(150),
  "status" varchar(10) NOT NULL CHECK ("status" IN ('Ditagihkan', 'Dibayar')),
  CONSTRAINT "inventaris_titip_faktur_pkey" PRIMARY KEY ("no_tagihan")
);

-- Tabel ipsrs_detail_hibah
CREATE TABLE "ipsrs_detail_hibah" (
  "no_hibah" varchar(20) NOT NULL,
  "kode_brng" varchar(15) DEFAULT '' NOT NULL,
  "kode_sat" varchar(4) NOT NULL,
  "jumlah" double precision,
  "h_hibah" double precision,
  "subtotalhibah" double precision,
  CONSTRAINT "ipsrs_detail_hibah_pkey" PRIMARY KEY ("no_hibah", "kode_brng")
);

-- Tabel ipsrs_detail_returbeli
CREATE TABLE "ipsrs_detail_returbeli" (
  "no_retur_beli" varchar(15) NOT NULL,
  "no_faktur" varchar(20) NOT NULL,
  "kode_brng" varchar(15) DEFAULT '' NOT NULL,
  "kode_sat" varchar(4),
  "h_beli" double precision,
  "h_retur" double precision,
  "jml_retur" double precision,
  "total" double precision
);

-- Tabel ipsrs_detail_titip_faktur
CREATE TABLE "ipsrs_detail_titip_faktur" (
  "no_tagihan" varchar(20) NOT NULL,
  "no_faktur" varchar(20) NOT NULL,
  CONSTRAINT "ipsrs_detail_titip_faktur_pkey" PRIMARY KEY ("no_tagihan", "no_faktur")
);

-- Tabel ipsrs_hibah
CREATE TABLE "ipsrs_hibah" (
  "no_hibah" varchar(20) NOT NULL,
  "kode_pemberi" varchar(5),
  "nip" varchar(20),
  "tgl_hibah" date,
  "totalhibah" double precision NOT NULL,
  "keterangan" varchar(100) NOT NULL,
  CONSTRAINT "ipsrs_hibah_pkey" PRIMARY KEY ("no_hibah")
);

-- Tabel ipsrs_riwayat_barang
CREATE TABLE "ipsrs_riwayat_barang" (
  "kode_brng" varchar(15),
  "stok_awal" double precision,
  "masuk" double precision,
  "keluar" double precision,
  "stok_akhir" double precision NOT NULL,
  "posisi" varchar(15) CHECK ("posisi" IN ('Pengadaan', 'Penerimaan', 'Retur Beli', 'Opname', 'Stok Keluar', 'Pengambilan UTD', 'Hibah')),
  "tanggal" date,
  "jam" time,
  "petugas" varchar(20),
  "status" varchar(6) CHECK ("status" IN ('Simpan', 'Hapus'))
);

-- Tabel ipsrs_titip_faktur
CREATE TABLE "ipsrs_titip_faktur" (
  "no_tagihan" varchar(20) NOT NULL,
  "tanggal" date,
  "nip" varchar(20),
  "keterangan" varchar(150),
  "status" varchar(10) NOT NULL CHECK ("status" IN ('Ditagihkan', 'Dibayar')),
  CONSTRAINT "ipsrs_titip_faktur_pkey" PRIMARY KEY ("no_tagihan")
);

-- Tabel ipsrsbarang
CREATE TABLE "ipsrsbarang" (
  "kode_brng" varchar(15) NOT NULL,
  "nama_brng" varchar(80) NOT NULL,
  "kode_sat" varchar(4) NOT NULL,
  "jenis" varchar(5),
  "stok" double precision NOT NULL,
  "harga" double precision NOT NULL,
  "status" varchar(1) NOT NULL CHECK ("status" IN ('0', '1')),
