-- Tabel laporan_anestesi
CREATE TABLE "laporan_anestesi" (
  "no_rawat" varchar(17) NOT NULL,
  "mulai" timestamp NOT NULL,
  "selesai" timestamp NOT NULL,
  "tempat_pemantauan" varchar(9) CHECK ("tempat_pemantauan" IN ('OK', 'Cathlab', 'ICU/ICCU', 'Radiologi', 'Endoscopy')),
  "tindakan_operasi" varchar(60) NOT NULL,
  "operator1" varchar(20) NOT NULL,
  "asisten_operator" varchar(20) NOT NULL,
  "dokter_anestesi" varchar(20) NOT NULL,
  "operator2" varchar(20) NOT NULL,
  "onloop" varchar(20) NOT NULL,
  "penata_anestesi" varchar(20) NOT NULL,
  "diagnosa_preop" varchar(100) NOT NULL,
  "diagnosa_postop" varchar(100) NOT NULL,
  "status_asa" varchar(1) CHECK ("status_asa" IN ('1', '2', '3', '4', '5', 'E')),
  "karena" varchar(40),
  "premedikasi" varchar(500),
  "ttv_premedikasi_td" varchar(8) NOT NULL,
  "ttv_premedikasi_rr" varchar(5) NOT NULL,
  "ttv_premedikasi_hr" varchar(5) NOT NULL,
  "ttv_premedikasi_spo2" varchar(5) NOT NULL,
  "ttv_premedikasi_ekg" varchar(5) NOT NULL,
  "ttv_premedikasi_suhu" varchar(5) NOT NULL,
  "ttv_premedikasi_lain" varchar(30) NOT NULL,
  "lama_operasi" varchar(10) NOT NULL,
  "lama_anastesi" varchar(10) NOT NULL,
  "keadaan_umum_bb" varchar(5) NOT NULL,
  "keadaan_umum_tb" varchar(5) NOT NULL,
  "keadaan_umum_alergi" varchar(50) NOT NULL,
  "keadaan_umum_malampathy" varchar(50) NOT NULL,
  "keadaan_umum_e" varchar(1) NOT NULL,
  "keadaan_umum_v" varchar(1) NOT NULL,
  "keadaan_umum_m" varchar(1) NOT NULL,
  "jenis_anestesi_lokasi" varchar(30) NOT NULL,
  "jenis_anestesi_sedasi" varchar(6) NOT NULL CHECK ("jenis_anestesi_sedasi" IN ('Ringan', 'Sedang', 'Berat')),
  "jenis_anestesi_regional" varchar(8) NOT NULL CHECK ("jenis_anestesi_regional" IN ('Spinal', 'Epidural', 'Combined')),
  "jenis_anestesi_ga_ett" varchar(5) NOT NULL CHECK ("jenis_anestesi_ga_ett" IN ('Ya', 'Tidak')),
  "jenis_anestesi_ga_ntt" varchar(5) NOT NULL CHECK ("jenis_anestesi_ga_ntt" IN ('Ya', 'Tidak')),
  "jenis_anestesi_ga_ema" varchar(5) NOT NULL CHECK ("jenis_anestesi_ga_ema" IN ('Ya', 'Tidak')),
  "jenis_anestesi_ga_bm" varchar(5) NOT NULL CHECK ("jenis_anestesi_ga_bm" IN ('Ya', 'Tidak')),
  "posisi" varchar(40) NOT NULL,
  "perdarahan" varchar(40) NOT NULL,
  "urine" varchar(40) NOT NULL,
  "komplikasi" varchar(40) NOT NULL,
  "ekstubasi" varchar(40) NOT NULL,
  "jumlah_pack" varchar(10) NOT NULL,
  "dipindahkan_ke" varchar(40) NOT NULL,
  "serah_terima_pasien" varchar(9) NOT NULL CHECK ("serah_terima_pasien" IN ('RR', 'ICU/ICCU', 'NICU/PICU', 'ODC')),
  "catatan" varchar(100) NOT NULL,
  "nip_recovery_room" varchar(20) NOT NULL,
  CONSTRAINT "laporan_anestesi_pkey" PRIMARY KEY ("no_rawat", "mulai")
);

