-- Tabel pegawai
CREATE TABLE "pegawai" (
  "id" serial NOT NULL,
  "nik" varchar(20) NOT NULL,
  "nama" varchar(50) NOT NULL,
  "jk" varchar(6) NOT NULL CHECK ("jk" IN ('Pria', 'Wanita')),
  "jbtn" varchar(25) NOT NULL,
  "jnj_jabatan" varchar(5) NOT NULL,
  "kode_kelompok" varchar(3) NOT NULL,
  "kode_resiko" varchar(3) NOT NULL,
  "kode_emergency" varchar(3) NOT NULL,
  "departemen" varchar(4) NOT NULL,
  "bidang" varchar(15) NOT NULL,
  "stts_wp" varchar(5) NOT NULL,
  "stts_kerja" varchar(3) NOT NULL,
  "npwp" varchar(15) NOT NULL,
  "pendidikan" varchar(80) NOT NULL,
  "gapok" double precision NOT NULL,
  "tmp_lahir" varchar(20) NOT NULL,
  "tgl_lahir" date NOT NULL,
  "alamat" varchar(60) NOT NULL,
  "kota" varchar(20) NOT NULL,
  "mulai_kerja" date NOT NULL,
  "ms_kerja" varchar(4) NOT NULL CHECK ("ms_kerja" IN ('<1', 'PT', 'FT>1')),
  "indexins" varchar(4) NOT NULL,
  "bpd" varchar(50) NOT NULL,
  "rekening" varchar(25) NOT NULL,
  "stts_aktif" varchar(11) NOT NULL CHECK ("stts_aktif" IN ('AKTIF', 'CUTI', 'KELUAR', 'TENAGA LUAR', 'NON AKTIF')),
  "wajibmasuk" smallint NOT NULL,
  "pengurang" double precision NOT NULL,
  "indek" smallint NOT NULL,
  "mulai_kontrak" date,
  "cuti_diambil" integer NOT NULL,
  "dankes" double precision NOT NULL,
  "photo" varchar(500),
  "no_ktp" varchar(20) NOT NULL,
  CONSTRAINT "pegawai_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "pegawai_nik_2_key" UNIQUE ("nik")
);

-- Tabel pelaksanaan_informasi_edukasi
CREATE TABLE "pelaksanaan_informasi_edukasi" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "nik" varchar(20) NOT NULL,
  "materi_edukasi" varchar(1000),
  "keterangan" varchar(50),
  "diberikan_pada" varchar(9) NOT NULL CHECK ("diberikan_pada" IN ('Pasien', 'Keluarga', 'Lain-lain')),
  "keterangan_diberikan_pada" varchar(40) NOT NULL,
  "lama_edukasi" varchar(10),
  "metode_edukasi" varchar(11) CHECK ("metode_edukasi" IN ('Ceramah', 'Diskusi', 'Demonstrasi')),
  "hasil_verifikasi" varchar(14) CHECK ("hasil_verifikasi" IN ('Sudah Mengerti', 'Re-Edukasi', 'Re-Demonstrasi')),
  "status" varchar(5) CHECK ("status" IN ('Awal', 'Ulang')),
  CONSTRAINT "pelaksanaan_informasi_edukasi_pkey" PRIMARY KEY ("no_rawat", "tanggal")
);

-- Tabel pelayanan_informasi_obat
CREATE TABLE "pelayanan_informasi_obat" (
  "no_permintaan" varchar(20) NOT NULL,
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "metode" varchar(8) CHECK ("metode" IN ('Lisan', 'Tertulis', 'Telepon')),
  "penanya" varchar(70),
  "status_penanya" varchar(17) CHECK ("status_penanya" IN ('Pasien', 'Keluarga Pasien', 'Petugas Kesehatan')),
  "no_telp_penanya" varchar(30),
  "jenis_pertanyaan" varchar(21) CHECK ("jenis_pertanyaan" IN ('Identifikasi Obat', 'Interaksi Obat', 'Harga Obat', 'Kontraindikasi', 'Cara Pemakaian', 'Stabilitas', 'Dosis', 'Keracunan', 'Efek Samping Obat', 'Penggunaan Terapeutik', 'Farmakokinetika', 'Farmakodinamika', 'Ketersediaan Obat', 'Lain-lain')),
  "keterangan_jenis_pertanyaan" varchar(30),
  "uraian_pertanyaan" varchar(500),
  CONSTRAINT "pelayanan_informasi_obat_pkey" PRIMARY KEY ("no_permintaan")
);

-- Tabel pemantauan_ews_neonatus
CREATE TABLE "pemantauan_ews_neonatus" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "parameter1" varchar(7) CHECK ("parameter1" IN ('<= 29', '30 - 39', '40 - 60', '>= 61')),
  "skor1" varchar(1),
  "parameter2" varchar(7) CHECK ("parameter2" IN ('<= 90', '90 - 93', '>= 94')),
  "skor2" varchar(1),
  "parameter3" varchar(5) CHECK ("parameter3" IN ('Tidak', 'Ya')),
  "skor3" varchar(1),
  "parameter4" varchar(9) CHECK ("parameter4" IN ('<= 80', '81 - 119', '120 - 160', '161 - 180', '>= 181')),
  "skor4" varchar(1),
  "parameter5" varchar(6) CHECK ("parameter5" IN ('Berat', 'Ringan', 'Tidak')),
  "skor5" varchar(1),
  "parameter6" varchar(10) CHECK ("parameter6" IN ('>= 3 Detik', '<= 3 Detik')),
  "skor6" varchar(1),
  "parameter7" varchar(11) CHECK ("parameter7" IN ('<= 36,5', '36,5 - 37,5', '>= 37,5')),
  "skor7" varchar(1),
  "parameter8" varchar(5) CHECK ("parameter8" IN ('Pink', 'Pucat')),
  "skor8" varchar(1),
  "skor_total" varchar(2),
  "parameter_total" varchar(250),
  "code_blue" varchar(5) NOT NULL CHECK ("code_blue" IN ('Ya', 'Tidak')),
  "nip" varchar(20),
  CONSTRAINT "pemantauan_ews_neonatus_pkey" PRIMARY KEY ("no_rawat", "tanggal")
);

-- Tabel pemantauan_meows_obstetri
CREATE TABLE "pemantauan_meows_obstetri" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "parameter_pernapasan" varchar(7) CHECK ("parameter_pernapasan" IN ('>= 30', '21 - 30', '11 - 20', '< 12')),
  "skor_pernapasan" varchar(1),
  "parameter_saturasi" varchar(7) CHECK ("parameter_saturasi" IN ('> 95', '90 - 94', '< 90')),
  "skor_saturasi" varchar(1),
  "parameter_temperatur" varchar(9) CHECK ("parameter_temperatur" IN ('> 38', '35 - 35.9', '36 - 37.9', '< 35')),
  "skor_temperatur" varchar(1),
  "parameter_tekanan_darah_sistole" varchar(9) CHECK ("parameter_tekanan_darah_sistole" IN ('> 160', '150 - 159', '100 - 140', '90 - 99', '< 90')),
  "skor_tekanan_darah_sistole" varchar(1),
  "parameter_tekanan_darah_diastole" varchar(8) CHECK ("parameter_tekanan_darah_diastole" IN ('> 110', '90 - 109', '< 90')),
  "skor_tekanan_darah_diastole" varchar(1),
  "parameter_denyut_jantung" varchar(9) CHECK ("parameter_denyut_jantung" IN ('> 120', '100 - 120', '51 - 99', '40 - 50', '< 40')),
  "skor_denyut_jantung" varchar(1),
  "parameter_kesadaran" varchar(12) CHECK ("parameter_kesadaran" IN ('Alert', 'Verbal', 'Pain', 'Unresponsive')),
  "skor_kesadaran" varchar(1),
  "parameter_ketuban" varchar(5) CHECK ("parameter_ketuban" IN ('Khas', 'Busuk')),
  "skor_ketuban" varchar(1),
  "parameter_discharge" varchar(6) CHECK ("parameter_discharge" IN ('Normal', 'Banyak')),
  "skor_discharge" varchar(1),
  "parameter_proteinuria" varchar(7) CHECK ("parameter_proteinuria" IN ('Negatif', '+', '++>')),
  "skor_proteinuria" varchar(1),
  "skor_total" varchar(2) NOT NULL,
  "parameter_total" varchar(250),
  "code_blue" varchar(5) NOT NULL CHECK ("code_blue" IN ('Ya', 'Tidak')),
  "nip" varchar(20),
  CONSTRAINT "pemantauan_meows_obstetri_pkey" PRIMARY KEY ("no_rawat", "tanggal")
);

-- Tabel pemantauan_pews_anak
CREATE TABLE "pemantauan_pews_anak" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "parameter_perilaku" varchar(49) CHECK ("parameter_perilaku" IN ('Sadar / Bermain', 'Tidur / Perubahan Perilaku', 'Gelisah', 'Tidak Merespon Terhadap Nyeri Penurunan Kesadaran')),
  "skor_perilaku" varchar(1),
  "parameter_crt_atau_warna_kulit" varchar(16) CHECK ("parameter_crt_atau_warna_kulit" IN ('1 - 2 dtk / Pink', '3 dtk / Pucat', '4 dtk / Sianosis', '>=5 dtk / Mottle')),
  "skor_crt_atau_warna_kulit" varchar(1),
  "parameter_perespirasi" varchar(26) CHECK ("parameter_perespirasi" IN ('Tidak Ada Retraksi', 'Cuping Hidung / O2 1-3 Lpm', 'Retraksi Dada / O2 4-6 Lpm', 'Stridor / O2 7-8 Lpm')),
  "skor_perespirasi" varchar(1),
  "skor_total" varchar(1),
  "parameter_total" varchar(250),
  "nip" varchar(20),
  CONSTRAINT "pemantauan_pews_anak_pkey" PRIMARY KEY ("no_rawat", "tanggal")
);

-- Tabel pemantauan_pews_dewasa
CREATE TABLE "pemantauan_pews_dewasa" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "parameter_laju_respirasi" varchar(7) CHECK ("parameter_laju_respirasi" IN ('<= 5', '6 - 8', '9 - 11', '12 - 20', '21 - 24', '25 - 34', '>= 35')),
  "skor_laju_respirasi" varchar(1),
  "parameter_saturasi_oksigen" varchar(7) CHECK ("parameter_saturasi_oksigen" IN ('>= 95', '94 - 95', '92 - 93', '<= 92')),
  "skor_saturasi_oksigen" varchar(1),
  "parameter_suplemen_oksigen" varchar(5) CHECK ("parameter_suplemen_oksigen" IN ('Ya', 'Tidak')),
  "skor_suplemen_oksigen" varchar(1),
  "parameter_tekanan_darah_sistolik" varchar(9) CHECK ("parameter_tekanan_darah_sistolik" IN ('>= 220', '181 - 220', '111 - 180', '101 - 110', '91 - 100', '71 - 90', '<= 70')),
  "skor_tekanan_darah_sistolik" varchar(1),
  "parameter_laju_jantung" varchar(9) CHECK ("parameter_laju_jantung" IN ('>= 140', '131 - 140', '111 - 130', '91 - 110', '51 - 90', '41 - 50', '<= 40')),
  "skor_laju_jantung" varchar(1),
  "parameter_kesadaran" varchar(12) CHECK ("parameter_kesadaran" IN ('Sadar', 'Nyeri/Verbal', 'Unrespon')),
  "skor_kesadaran" varchar(1),
  "parameter_temperatur" varchar(9) CHECK ("parameter_temperatur" IN ('<= 35', '35.1 - 36', '36.1 - 38', '38.1 - 39', '>= 39')),
  "skor_temperatur" varchar(1),
  "skor_total" varchar(2),
  "parameter_total" varchar(250),
  "nip" varchar(20),
  CONSTRAINT "pemantauan_pews_dewasa_pkey" PRIMARY KEY ("no_rawat", "tanggal")
);

