-- Tabel pemeriksaan_obstetri_ralan
CREATE TABLE "pemeriksaan_obstetri_ralan" (
  "no_rawat" varchar(17) NOT NULL,
  "tgl_perawatan" date NOT NULL,
  "jam_rawat" time NOT NULL,
  "tinggi_uteri" varchar(5),
  "janin" varchar(7) CHECK ("janin" IN ('Tunggal', 'Gemelli', '-')),
  "letak" varchar(50),
  "panggul" varchar(3) CHECK ("panggul" IN ('-', '5/5', '4/5', '3/5', '2/5', '1/5')),
  "denyut" varchar(5),
  "kontraksi" varchar(1) CHECK ("kontraksi" IN ('+', '-')),
  "kualitas_mnt" varchar(5),
  "kualitas_dtk" varchar(5),
  "fluksus" varchar(1) CHECK ("fluksus" IN ('+', '-')),
  "albus" varchar(1) CHECK ("albus" IN ('+', '-')),
  "vulva" varchar(50),
  "portio" varchar(50),
  "dalam" varchar(6) CHECK ("dalam" IN ('Kenyal', 'Lunak')),
  "tebal" varchar(5),
  "arah" varchar(8) CHECK ("arah" IN ('depan', 'axial', 'belakang')),
  "pembukaan" varchar(50),
  "penurunan" varchar(50),
  "denominator" varchar(50) NOT NULL,
  "ketuban" varchar(1) CHECK ("ketuban" IN ('-', '+')),
  "feto" varchar(12) CHECK ("feto" IN ('Normal', 'Susp.CPD-FPD', 'CPD-FPD')),
  CONSTRAINT "pemeriksaan_obstetri_ralan_pkey" PRIMARY KEY ("no_rawat", "tgl_perawatan", "jam_rawat")
);

