  "target_sasaran" varchar(70) NOT NULL,
  "lokasi_kegiatan" varchar(70) NOT NULL,
  "jumlah" double precision NOT NULL,
  "harga" double precision NOT NULL,
  "total" double precision NOT NULL,
  "keterangan" varchar(70) NOT NULL,
  "nik_pj" varchar(20) NOT NULL,
  "status" varchar(16) NOT NULL CHECK ("status" IN ('Proses Pengajuan', 'Disetujui', 'Ditolak', 'Divalidasi')),
  CONSTRAINT "pengajuan_biaya_pkey" PRIMARY KEY ("no_pengajuan")
);

