-- Tabel pengkajian_restrain
CREATE TABLE "pengkajian_restrain" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "nip" varchar(20) NOT NULL,
  "gcs" varchar(5),
  "refleka_cahaya_ka" varchar(3),
  "refleka_cahaya_ki" varchar(3),
  "ukuran_pupil_ka" varchar(3),
  "ukuran_pupil_ki" varchar(3),
  "td" varchar(8),
  "suhu" varchar(5),
  "rr" varchar(5),
  "nadi" varchar(5),
  "hasil_observasi" varchar(77) CHECK ("hasil_observasi" IN ('Pasien Gelisah/Delirium Dan Berontak', 'Pasien Tidak Kooperatif', 'Ketidakmampuan Dalam Mengikuti Perintah Untuk Tidak Meninggalkan Tempat Tidur')),
  "pertimbangan_klinis" varchar(25) CHECK ("pertimbangan_klinis" IN ('Membahayakan Diri Sendiri', 'Membahayakan Orang Lain')),
  "restrain_non_farmakologi" varchar(27) CHECK ("restrain_non_farmakologi" IN ('Restrain Pergelangan Tangan', 'Restrain Pergelangan Kaki', 'Restrain Badan', 'Lain-lain')),
  "restrain_non_farmakologi_keterangan" varchar(50),
  "restrain_farmakologi" varchar(200),
  "sudah_dijelaskan_keluarga" varchar(5) NOT NULL CHECK ("sudah_dijelaskan_keluarga" IN ('Sudah', 'Belum')),
  "keluarga_yang_menyetujui" varchar(100),
  CONSTRAINT "pengkajian_restrain_pkey" PRIMARY KEY ("no_rawat")
);

