-- Tabel penilaian_awal_keperawatan_ranap
CREATE TABLE "penilaian_awal_keperawatan_ranap" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "informasi" varchar(13) NOT NULL CHECK ("informasi" IN ('Autoanamnesis', 'Alloanamnesis')),
  "ket_informasi" varchar(30) NOT NULL,
  "tiba_diruang_rawat" varchar(19) NOT NULL CHECK ("tiba_diruang_rawat" IN ('Jalan Tanpa Bantuan', 'Kursi Roda', 'Brankar')),
  "kasus_trauma" varchar(10) CHECK ("kasus_trauma" IN ('Trauma', 'Non Trauma')),
  "cara_masuk" varchar(9) NOT NULL CHECK ("cara_masuk" IN ('Poli', 'IGD', 'Lain-lain')),
  "rps" varchar(300) NOT NULL,
  "rpd" varchar(100) NOT NULL,
  "rpk" varchar(100) NOT NULL,
  "rpo" varchar(100) NOT NULL,
  "riwayat_pembedahan" varchar(40) NOT NULL,
  "riwayat_dirawat_dirs" varchar(40) NOT NULL,
  "alat_bantu_dipakai" varchar(17) NOT NULL CHECK ("alat_bantu_dipakai" IN ('Tidak Ada', 'Kacamata', 'Prothesa', 'Alat Bantu Dengar', 'Lain-lain')),
  "riwayat_kehamilan" varchar(5) NOT NULL CHECK ("riwayat_kehamilan" IN ('Tidak', 'Ya')),
  "riwayat_kehamilan_perkiraan" varchar(30) NOT NULL,
  "riwayat_tranfusi" varchar(40) NOT NULL,
  "riwayat_alergi" varchar(40) NOT NULL,
  "riwayat_merokok" varchar(5) NOT NULL CHECK ("riwayat_merokok" IN ('Tidak', 'Ya')),
  "riwayat_merokok_jumlah" varchar(5) NOT NULL,
  "riwayat_alkohol" varchar(5) NOT NULL CHECK ("riwayat_alkohol" IN ('Tidak', 'Ya')),
  "riwayat_alkohol_jumlah" varchar(5) NOT NULL,
  "riwayat_narkoba" varchar(5) NOT NULL CHECK ("riwayat_narkoba" IN ('Tidak', 'Ya')),
  "riwayat_olahraga" varchar(5) NOT NULL CHECK ("riwayat_olahraga" IN ('Tidak', 'Ya')),
  "pemeriksaan_mental" varchar(40) NOT NULL,
  "pemeriksaan_keadaan_umum" varchar(6) NOT NULL CHECK ("pemeriksaan_keadaan_umum" IN ('Baik', 'Sedang', 'Buruk')),
  "pemeriksaan_gcs" varchar(10) NOT NULL,
  "pemeriksaan_td" varchar(8) NOT NULL,
  "pemeriksaan_nadi" varchar(5) NOT NULL,
  "pemeriksaan_rr" varchar(5) NOT NULL,
  "pemeriksaan_suhu" varchar(5) NOT NULL,
  "pemeriksaan_spo2" varchar(5) NOT NULL,
  "pemeriksaan_bb" varchar(5) NOT NULL,
  "pemeriksaan_tb" varchar(5) NOT NULL,
  "pemeriksaan_susunan_kepala" varchar(13) NOT NULL CHECK ("pemeriksaan_susunan_kepala" IN ('TAK', 'Hydrocephalus', 'Hematoma', 'Lain-lain')),
  "pemeriksaan_susunan_kepala_keterangan" varchar(50) NOT NULL,
  "pemeriksaan_susunan_wajah" varchar(19) NOT NULL CHECK ("pemeriksaan_susunan_wajah" IN ('TAK', 'Asimetris', 'Kelainan Kongenital')),
