  "rpd" varchar(150) NOT NULL,
  "rpk" varchar(150) NOT NULL,
  "rpo" varchar(150) NOT NULL,
  "alergi" varchar(40) NOT NULL,
  "tumbuh_kembang_tengkurap" varchar(15),
