  "persalinan_kelahiran_keterangan" varchar(30) NOT NULL,
  "persalinan_umur_kelahiran" varchar(12) NOT NULL CHECK ("persalinan_umur_kelahiran" IN ('Cukup Bulan', 'Kurang Bulan')),
  "persalinan_kelainan_bawaan" varchar(9) NOT NULL CHECK ("persalinan_kelainan_bawaan" IN ('Tidak Ada', 'Ada')),
  "persalinan_kelainan_bawaan_keterangan" varchar(30) NOT NULL,
  "persalinan_bb_lahir" varchar(5) NOT NULL,
  "persalinan_pb_lahir" varchar(5) NOT NULL,
  "persalinan_lainnya" varchar(100) NOT NULL,
  "fisik_kesadaran" varchar(13) NOT NULL CHECK ("fisik_kesadaran" IN ('Compos Mentis', 'Apatis', 'Somnolen', 'Sopor', 'Soporcoma', 'Coma')),
  "fisik_gcs" varchar(6) NOT NULL,
  "fisik_td" varchar(8) NOT NULL,
  "fisik_rr" varchar(5) NOT NULL,
  "fisik_suhu" varchar(5) NOT NULL,
  "fisik_nadi" varchar(5) NOT NULL,
  "fisik_bb" varchar(5) NOT NULL,
  "fisik_tb" varchar(5) NOT NULL,
  "fisik_lp" varchar(5) NOT NULL,
  "fisik_lk" varchar(5) NOT NULL,
  "fisik_ld" varchar(5) NOT NULL,
  "saraf_pusat_kepala" varchar(13) NOT NULL CHECK ("saraf_pusat_kepala" IN ('TAK', 'Hydrocephalus', 'Hematoma', 'Lain-lain')),
  "saraf_pusat_kepala_keterangan" varchar(30) NOT NULL,
  "saraf_pusat_wajah" varchar(19) NOT NULL CHECK ("saraf_pusat_wajah" IN ('TAK', 'Asimetris', 'Kelainan Kongenital')),
  "saraf_pusat_wajah_keterangan" varchar(30) NOT NULL,
  "saraf_pusat_leher" varchar(18) NOT NULL CHECK ("saraf_pusat_leher" IN ('TAK', 'Kaku Kuduk', 'Pembesaran Thyroid', 'Pembesaran KGB')),
  "saraf_pusat_kejang" varchar(4) NOT NULL CHECK ("saraf_pusat_kejang" IN ('TAK', 'Kuat', 'Ada')),
  "saraf_pusat_kejang_keterangan" varchar(30) NOT NULL,
  "saraf_pusat_sensorik" varchar(11) NOT NULL CHECK ("saraf_pusat_sensorik" IN ('TAK', 'Sakit Nyeri', 'Rasa Kebas')),
  "kardiovaskuler_pulsasi" varchar(9) NOT NULL CHECK ("kardiovaskuler_pulsasi" IN ('Kuat', 'Lemah', 'Lain-lain')),
  "kardiovaskuler_sirkulasi" varchar(12) NOT NULL CHECK ("kardiovaskuler_sirkulasi" IN ('Akral Hangat', 'Akral Dingin', 'Edema')),
  "kardiovaskuler_sirkulasi_keterangan" varchar(30) NOT NULL,
  "kardiovaskuler_denyut_nadi" varchar(13) NOT NULL CHECK ("kardiovaskuler_denyut_nadi" IN ('Teratur', 'Tidak Teratur')),
  "respirasi_retraksi" varchar(9) NOT NULL CHECK ("respirasi_retraksi" IN ('Tidak Ada', 'Ringan', 'Berat')),
  "respirasi_pola_nafas" varchar(9) NOT NULL CHECK ("respirasi_pola_nafas" IN ('Normal', 'Bradipnea', 'Tachipnea')),
  "respirasi_suara_nafas" varchar(9) NOT NULL CHECK ("respirasi_suara_nafas" IN ('Vesikuler', 'Wheezing', 'Rhonki')),
  "respirasi_batuk" varchar(18) NOT NULL CHECK ("respirasi_batuk" IN ('Tidak', 'Ya : Produktif', 'Ya : Non Produktif')),
  "respirasi_volume" varchar(14) NOT NULL CHECK ("respirasi_volume" IN ('Normal', 'Hiperventilasi', 'Hipoventilasi')),
  "respirasi_jenis_pernapasan" varchar(22) NOT NULL CHECK ("respirasi_jenis_pernapasan" IN ('Pernafasan Dada', 'Alat Bantu Pernafasaan')),
  "respirasi_jenis_pernapasan_keterangan" varchar(30) NOT NULL,
  "respirasi_irama" varchar(13) NOT NULL CHECK ("respirasi_irama" IN ('Teratur', 'Tidak Teratur')),
  "gastro_mulut" varchar(13) NOT NULL CHECK ("gastro_mulut" IN ('TAK', 'Stomatitis', 'Mukosa Kering', 'Bibir Pucat', 'Lain-lain')),
  "gastro_mulut_keterangan" varchar(30) NOT NULL,
  "gastro_tenggorakan" varchar(16) NOT NULL CHECK ("gastro_tenggorakan" IN ('TAK', 'Gangguan Menelan', 'Sakit Menelan', 'Lain-lain')),
  "gastro_tenggorakan_keterangan" varchar(30) NOT NULL,
  "gastro_lidah" varchar(15) NOT NULL CHECK ("gastro_lidah" IN ('TAK', 'Kotor', 'Gerak Asimetris', 'Lain-lain')),
  "gastro_lidah_keterangan" varchar(30) NOT NULL,
  "gastro_abdomen" varchar(17) NOT NULL CHECK ("gastro_abdomen" IN ('Supel', 'Asictes', 'Tegang', 'Nyeri Tekan/Lepas', 'Lain-lain')),
  "gastro_abdomen_keterangan" varchar(30) NOT NULL,
  "gastro_gigi" varchar(9) NOT NULL CHECK ("gastro_gigi" IN ('TAK', 'Karies', 'Goyang', 'Lain-lain')),
  "gastro_gigi_keterangan" varchar(30) NOT NULL,
  "gastro_usus" varchar(21) NOT NULL CHECK ("gastro_usus" IN ('TAK', 'Tidak Ada Bising Usus', 'Hiperistaltik')),
  "gastro_anus" varchar(11) NOT NULL CHECK ("gastro_anus" IN ('TAK', 'Atresia Ani')),
  "neurologi_sensorik" varchar(11) NOT NULL CHECK ("neurologi_sensorik" IN ('TAK', 'Sakit Nyeri', 'Rasa Kebas', 'Lain-lain')),
  "neurologi_pengilihatan" varchar(12) NOT NULL CHECK ("neurologi_pengilihatan" IN ('TAK', 'Ada Kelainan')),
  "neurologi_pengilihatan_keterangan" varchar(30) NOT NULL,
  "neurologi_alat_bantu_penglihatan" varchar(12) NOT NULL CHECK ("neurologi_alat_bantu_penglihatan" IN ('Tidak', 'Kacamata', 'Lensa Kontak')),
  "neurologi_motorik" varchar(11) NOT NULL CHECK ("neurologi_motorik" IN ('TAK', 'Hemiparese', 'Tetraparese', 'Tremor', 'Lain-lain')),
  "neurologi_pendengaran" varchar(13) NOT NULL CHECK ("neurologi_pendengaran" IN ('TAK', 'Berdengung', 'Nyeri', 'Tuli', 'Keluar Cairan', 'Lain-lain')),
  "neurologi_bicara" varchar(11) NOT NULL CHECK ("neurologi_bicara" IN ('Jelas', 'Tidak Jelas')),
  "neurologi_bicara_keterangan" varchar(30) NOT NULL,
  "neurologi_otot" varchar(5) NOT NULL CHECK ("neurologi_otot" IN ('Kuat', 'Lemah')),
  "inte_kulit" varchar(14) NOT NULL CHECK ("inte_kulit" IN ('Normal', 'Rash/Kemerahan', 'Luka', 'Memar', 'Ptekie', 'Bula')),
  "inte_warna_kulit" varchar(9) NOT NULL CHECK ("inte_warna_kulit" IN ('Normal', 'Pucat', 'Sianosis', 'Lain-lain')),
  "inte_tugor" varchar(6) NOT NULL CHECK ("inte_tugor" IN ('Baik', 'Sedang', 'Buruk')),
  "inte_decubi" varchar(30) NOT NULL CHECK ("inte_decubi" IN ('Tidak Ada', 'Usia > 65 tahun', 'Obesitas', 'Imobilisasi', 'Paraplegi/Vegetative State', 'Dirawat Di HCU', 'Penyakit Kronis (DM, CHF, CKD)', 'Inkontinentia Uri/Alvi')),
  "musku_odema" varchar(9) NOT NULL CHECK ("musku_odema" IN ('Tidak Ada', 'Ada')),
  "musku_odema_keterangan" varchar(30) NOT NULL,
  "musku_pegerakansendi" varchar(8) NOT NULL CHECK ("musku_pegerakansendi" IN ('Bebas', 'Terbatas')),
  "musku_otot" varchar(6) NOT NULL CHECK ("musku_otot" IN ('Baik', 'Lemah', 'Tremor')),
  "musku_fraktur" varchar(9) NOT NULL CHECK ("musku_fraktur" IN ('Tidak Ada', 'Ada')),
  "musku_fraktur_keterangan" varchar(30) NOT NULL,
  "musku_nyerisendi" varchar(9) NOT NULL CHECK ("musku_nyerisendi" IN ('Tidak Ada', 'Ada')),
  "musku_nyerisendi_keterangan" varchar(30) NOT NULL,
  "eliminasi_bab_frekuensi" varchar(3) NOT NULL,
  "eliminasi_bab_frekuensi_per" varchar(10) NOT NULL,
  "eliminasi_bab_konsistesi" varchar(20) NOT NULL,
  "eliminasi_bab_warna" varchar(20) NOT NULL,
  "eliminasi_bak_frekuensi" varchar(3) NOT NULL,
  "eliminasi_bak_frekuensi_per" varchar(10) NOT NULL,
  "eliminasi_bak_warna" varchar(20) NOT NULL,
  "eliminasi_bak_lainlain" varchar(20) NOT NULL,
  "psiko_kondisi" varchar(17) NOT NULL CHECK ("psiko_kondisi" IN ('Tidak Ada Masalah', 'Marah', 'Takut', 'Depresi', 'Cepat Lelah', 'Cemas', 'Gelisah', 'Sulit Tidur', 'Lain-lain')),
  "psiko_perilaku" varchar(34) NOT NULL CHECK ("psiko_perilaku" IN ('Tidak Ada Masalah', 'Perilaku Kekerasan', 'Gangguan Efek', 'Gangguan Memori', 'Halusinasi', 'Kecenderungan Percobaan Bunuh Diri', 'Lain-lain')),
  "psiko_perilaku_keterangan" varchar(30) NOT NULL,
  "psiko_gangguan_jiwa" varchar(5) NOT NULL CHECK ("psiko_gangguan_jiwa" IN ('Tidak', 'Ya')),
  "psiko_hubungan_pasien" varchar(15) NOT NULL CHECK ("psiko_hubungan_pasien" IN ('Harmonis', 'Kurang Harmonis', 'Tidak Harmonis', 'Konflik Besar')),
  "psiko_tinggal_dengan" varchar(12) NOT NULL CHECK ("psiko_tinggal_dengan" IN ('Sendiri', 'Orang Tua', 'Panti Asuhan', 'Keluarga', 'Lain-lain')),
  "psiko_tinggal_dengan_keterangan" varchar(30) NOT NULL,
  "psiko_pekerjaan_pj" varchar(30) NOT NULL,
  "psiko_nilai_kepercayaan" varchar(9) NOT NULL CHECK ("psiko_nilai_kepercayaan" IN ('Tidak Ada', 'Ada')),
  "psiko_nilai_kepercayaan_keterangan" varchar(30) NOT NULL,
  "psiko_pendidikan_pj" varchar(14) NOT NULL CHECK ("psiko_pendidikan_pj" IN ('-', 'TS', 'TK', 'SD', 'SMP', 'SMA', 'SLTA/SEDERAJAT', 'D1', 'D2', 'D3', 'D4', 'S1', 'S2', 'S3')),
  "psiko_edukasi" varchar(8) NOT NULL CHECK ("psiko_edukasi" IN ('Pasien', 'Keluarga', 'Lainnya')),
  "psiko_edukasi_keterangan" varchar(30) NOT NULL,
  "edukasi_bahasa" varchar(30) NOT NULL,
  "edukasi_baca_tulis" varchar(10) NOT NULL CHECK ("edukasi_baca_tulis" IN ('Baik', 'Kurang', 'Tidak Bisa')),
  "edukasi_penerjemah" varchar(5) NOT NULL CHECK ("edukasi_penerjemah" IN ('Tidak', 'Ya')),
  "edukasi_penerjemah_keterangan" varchar(30) NOT NULL,
  "edukasi_terdapat_hambatan" varchar(5) NOT NULL CHECK ("edukasi_terdapat_hambatan" IN ('Tidak', 'Ya')),
  "edukasi_hambatan_belajar" varchar(22) NOT NULL CHECK ("edukasi_hambatan_belajar" IN ('-', 'Gangguan Pendengaran', 'Gangguan Penglihatan', 'Gangguan Kognitif', 'Gangguan Fisik', 'Gangguan Emosi', 'Keterbatasan Bahasa', 'Keterbatasan Budaya', 'Keterbatasan Spiritual', 'Agama', 'Lainnya')),
  "edukasi_hambatan_belajar_keterangan" varchar(30) NOT NULL,
  "edukasi_hambatan_bicara" varchar(15) NOT NULL CHECK ("edukasi_hambatan_bicara" IN ('Normal', 'Gangguan Bicara')),
  "edukasi_bahasa_isyarat" varchar(5) NOT NULL CHECK ("edukasi_bahasa_isyarat" IN ('Tidak', 'Ya')),
  "edukasi_cara_belajar" varchar(11) NOT NULL CHECK ("edukasi_cara_belajar" IN ('Audio', 'Lisan', 'Visual', 'Demonstrasi', 'Tulisan')),
  "edukasi_menerima_informasi" varchar(5) NOT NULL CHECK ("edukasi_menerima_informasi" IN ('Ya', 'Tidak')),
  "edukasi_menerima_informasi_keterangan" varchar(30) NOT NULL,
  "edukasi_nutrisi" varchar(5) NOT NULL CHECK ("edukasi_nutrisi" IN ('Ya', 'Tidak')),
  "edukasi_penyakit" varchar(5) NOT NULL CHECK ("edukasi_penyakit" IN ('Ya', 'Tidak')),
  "edukasi_pengobatan" varchar(5) NOT NULL CHECK ("edukasi_pengobatan" IN ('Ya', 'Tidak')),
  "edukasi_perawatan" varchar(5) NOT NULL CHECK ("edukasi_perawatan" IN ('Ya', 'Tidak')),
  "skrining_gizi1" varchar(5) NOT NULL CHECK ("skrining_gizi1" IN ('Tidak', 'Ya')),
  "nilai_gizi1" varchar(1) NOT NULL,
  "skrining_gizi2" varchar(5) NOT NULL CHECK ("skrining_gizi2" IN ('Tidak', 'Ya')),
  "nilai_gizi2" varchar(1) NOT NULL,
  "skrining_gizi3" varchar(5) NOT NULL CHECK ("skrining_gizi3" IN ('Tidak', 'Ya')),
  "nilai_gizi3" varchar(1) NOT NULL,
  "skrining_gizi4" varchar(5) NOT NULL CHECK ("skrining_gizi4" IN ('Tidak', 'Ya')),
  "nilai_gizi4" varchar(1) NOT NULL,
  "total_nilai" varchar(2) NOT NULL,
  "keterangan_skrining_gizi" varchar(50) NOT NULL,
  "penilaian_humptydumpty_skala1" varchar(12) CHECK ("penilaian_humptydumpty_skala1" IN ('0 - 3 Tahun', '3 - 7 Tahun', '7 - 13 Tahun', '> 13 Tahun')),
  "penilaian_humptydumpty_nilai1" smallint,
  "penilaian_humptydumpty_skala2" varchar(9) CHECK ("penilaian_humptydumpty_skala2" IN ('Laki-laki', 'Perempuan')),
  "penilaian_humptydumpty_nilai2" smallint,
  "penilaian_humptydumpty_skala3" varchar(96) CHECK ("penilaian_humptydumpty_skala3" IN ('Kelainan Neurologi', 'Perubahan Dalam Oksigen(Masalah Saluran Nafas, Dehidrasi, Anemia, Anoreksia / Sakit Kepala, Dll)', 'Kelainan Psikis / Perilaku', 'Diagnosa Lain')),
  "penilaian_humptydumpty_nilai3" smallint,
  "penilaian_humptydumpty_skala4" varchar(33) CHECK ("penilaian_humptydumpty_skala4" IN ('Tidak Sadar Terhadap Keterbatasan', 'Lupa Keterbatasan', 'Mengetahui Kemampuan Diri')),
  "penilaian_humptydumpty_nilai4" smallint,
  "penilaian_humptydumpty_skala5" varchar(46) CHECK ("penilaian_humptydumpty_skala5" IN ('Riwayat Jatuh Dari Tempat Tidur Saat Bayi/Anak', 'Pasien Menggunakan Alat Bantu/Box/Mebel', 'Pasien Berada Di Tempat Tidur', 'Di Luar Ruang Rawat')),
  "penilaian_humptydumpty_nilai5" smallint,
  "penilaian_humptydumpty_skala6" varchar(12) CHECK ("penilaian_humptydumpty_skala6" IN ('Dalam 24 Jam', 'Dalam 48 Jam', '> 48 Jam')),
  "penilaian_humptydumpty_nilai6" smallint,
  "penilaian_humptydumpty_skala7" varchar(186) CHECK ("penilaian_humptydumpty_skala7" IN ('Bermacam-macam Obat Yang Digunakan : Obat Sedative (Kecuali Pasien ICU Yang Menggunakan sedasi dan paralisis), Hipnotik, Barbiturat, Fenoti-Azin, Antidepresan, Laksans/Diuretika,Narkotik', 'Salah Satu Dari Pengobatan Di Atas', 'Pengobatan Lain')),
  "penilaian_humptydumpty_nilai7" smallint,
  "penilaian_humptydumpty_totalnilai" smallint,
  "hasil_skrining_penilaian_humptydumpty" varchar(50),
  "nyeri_wajah" varchar(47) NOT NULL CHECK ("nyeri_wajah" IN ('Tersenyum/tidak ada ekspresi khusus', 'Terkadang meringis/menarik diri', 'Sering menggetarkan dagu dan mengatupkan rahang')),
  "nyeri_nilai_wajah" varchar(1) NOT NULL,
  "nyeri_kaki" varchar(29) NOT NULL CHECK ("nyeri_kaki" IN ('Gerakan normal/relaksasi', 'Tidak tenang/tegang', 'Kaki dibuat menendang/menarik')),
  "nyeri_nilai_kaki" varchar(1) NOT NULL,
  "nyeri_aktifitas" varchar(38) NOT NULL CHECK ("nyeri_aktifitas" IN ('Tidur posisi normal, mudah bergerak', 'Gerakan menggeliat/berguling, kaku', 'Melengkungkan punggung/kaku menghentak')),
  "nyeri_nilai_aktifitas" varchar(1) NOT NULL,
  "nyeri_menangis" varchar(41) NOT NULL CHECK ("nyeri_menangis" IN ('Tidak menangis (mudah bergerak)', 'Mengerang/merengek', 'Menangis terus menerus, terisak, menjerit')),
  "nyeri_nilai_menangis" varchar(1) NOT NULL,
  "nyeri_bersuara" varchar(44) NOT NULL CHECK ("nyeri_bersuara" IN ('Bersuara normal/tenang', 'Tenang bila dipeluk, digendong/diajak bicara', 'Sulit untuk menenangkan')),
  "nyeri_nilai_bersuara" varchar(1) NOT NULL,
  "nyeri_nilai_total" varchar(2) NOT NULL,
  "nyeri_kondisi" varchar(15) NOT NULL CHECK ("nyeri_kondisi" IN ('Tidak Ada Nyeri', 'Nyeri Akut', 'Nyeri Kronis')),
  "nyeri_lokasi" varchar(50) NOT NULL,
  "nyeri_durasi" varchar(25) NOT NULL,
  "nyeri_frekuensi" varchar(25) NOT NULL,
  "nyeri_hilang" varchar(20) NOT NULL CHECK ("nyeri_hilang" IN ('Minum Obat', 'Istirahat', 'Mendengar Music', 'Berubah Posisi/Tidur', 'Lain-lain')),
  "nyeri_hilang_keterangan" varchar(40) NOT NULL,
  "nyeri_diberitahukan_pada_dokter" varchar(5) NOT NULL CHECK ("nyeri_diberitahukan_pada_dokter" IN ('Tidak', 'Ya')),
  "nyeri_diberitahukan_pada_dokter_keterangan" varchar(15) NOT NULL,
  "informasi_perencanaan_pulang" varchar(5) NOT NULL CHECK ("informasi_perencanaan_pulang" IN ('Ya', 'Tidak')),
  "lama_ratarata" varchar(3) NOT NULL,
  "perencanaan_pulang" date NOT NULL,
  "kondisi_klinis_pulang" varchar(100) NOT NULL,
  "perawatan_lanjutan_dirumah" varchar(300) NOT NULL,
  "cara_transportasi_pulang" varchar(19) NOT NULL CHECK ("cara_transportasi_pulang" IN ('Mandiri', 'Dibantu Sebagian', 'Dibantu Keseluruhan', 'Menggunakan Rostul', 'Menggunakan Brankar', 'Berjalan')),
  "transportasi_digunakan" varchar(17) NOT NULL CHECK ("transportasi_digunakan" IN ('Kendaraan Pribadi', 'Mobil Ambulance', 'Kendaraan Umum')),
  "rencana" varchar(200),
  "nip1" varchar(20) NOT NULL,
  "nip2" varchar(20) NOT NULL,
  "kd_dokter" varchar(20) NOT NULL,
  CONSTRAINT "penilaian_awal_keperawatan_ranap_bayi_pkey" PRIMARY KEY ("no_rawat")
);

