-- Tabel penilaian_awal_keperawatan_ranap_neonatus
CREATE TABLE "penilaian_awal_keperawatan_ranap_neonatus" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "asal_pasien" varchar(14) CHECK ("asal_pasien" IN ('IGD', 'Poliklinik', 'Kamar Bersalin', 'Kamar Operasi')),
  "cara_masuk" varchar(10) CHECK ("cara_masuk" IN ('Baby Box', 'Inkubator', 'Kursi Roda')),
  "diperoleh_dari" varchar(30),
  "hubungan_dengan_pasien" varchar(30),
  "keluhan_utama" varchar(300),
  "prenatal_g" varchar(10),
  "prenatal_p" varchar(10),
  "prenatal_a" varchar(10),
  "prenatal_uk" varchar(30),
  "prenatal_riwayat_penyakit_ibu" varchar(10) CHECK ("prenatal_riwayat_penyakit_ibu" IN ('Tidak Ada', 'DM', 'Hipertensi', 'Jantung', 'TBC', 'Hep B', 'Asma', 'PMS', 'Lainnya')),
  "prenatal_riwayat_penyakit_ibu_keterangan" varchar(30),
  "prenatal_riwayat_pengobatan_ibu_selama_hamil" varchar(100),
  "prenatal_pernah_dirawat" varchar(5) CHECK ("prenatal_pernah_dirawat" IN ('Ya', 'Tidak')),
  "prenatal_pernah_dirawat_keterangan" varchar(50),
  "prenatal_status_gizi_ibu" varchar(5) CHECK ("prenatal_status_gizi_ibu" IN ('Baik', 'Buruk')),
  "intranatal_g" varchar(10),
  "intranatal_p" varchar(10),
  "intranatal_a" varchar(10),
  "intranatal_kondisi_lahir" varchar(30),
  "intranatal_cara_persalinan" varchar(16) CHECK ("intranatal_cara_persalinan" IN ('Spontan', 'Vacum Ekstraksi', 'Forcep Ekstraksi', 'Sectio Caesarea', 'Lainnya')),
  "intranatal_cara_persalinan_keterangan" varchar(30),
  "intranatal_apgar" varchar(10),
  "intranatal_letak" varchar(30),
  "intranatal_tali_pusat" varchar(6) CHECK ("intranatal_tali_pusat" IN ('Segar', 'Layu', 'Simpul')),
  "intranatal_ketuban" varchar(11) NOT NULL CHECK ("intranatal_ketuban" IN ('Jernih', 'Darah', 'Putih Keruh', 'Hijau', 'Meconium')),
  "intranatal_bb" varchar(5) NOT NULL,
  "intranatal_pb" varchar(5) NOT NULL,
  "intranatal_lk" varchar(5) NOT NULL,
  "intranatal_ld" varchar(5) NOT NULL,
  "intranatal_lp" varchar(5) NOT NULL,
  "risiko_infeksi_mayor" varchar(18) NOT NULL CHECK ("risiko_infeksi_mayor" IN ('-', 'Ibu Demam >= 38° C', 'KPD > 24 Jam', 'Ketuban Hijau', 'Korioamniotis', 'Fetal Distress')),
  "risiko_infeksi_mayor_keterangan" varchar(30) NOT NULL,
  "risiko_infeksi_minor" varchar(22) NOT NULL CHECK ("risiko_infeksi_minor" IN ('-', 'KPD > 12 Jam', 'Asfiksia', 'BBLR', 'ISK', 'UK < 37 Minggu', 'Gemeli', 'Keputihan', 'Ibu Temperatur > 37° C')),
  "risiko_infeksi_minor_keterangan" varchar(30) NOT NULL,
  "kebutuhan_biologis_nutrisi" varchar(12) NOT NULL CHECK ("kebutuhan_biologis_nutrisi" IN ('Air Susu Ibu', 'Lainnya')),
  "kebutuhan_biologis_nutrisi_keterangan" varchar(50) NOT NULL,
  "kebutuhan_biologis_nutrisi_frekuensi" varchar(5) NOT NULL,
  "kebutuhan_biologis_nutrisi_kali" varchar(3) NOT NULL,
  "kebutuhan_biologis_bak" varchar(17) NOT NULL CHECK ("kebutuhan_biologis_bak" IN ('Ada Keluhan', 'Tidak Ada Keluhan')),
  "kebutuhan_biologis_bak_keterangan" varchar(30) NOT NULL,
  "kebutuhan_biologis_bab" varchar(17) NOT NULL CHECK ("kebutuhan_biologis_bab" IN ('Ada Keluhan', 'Tidak Ada Keluhan')),
  "kebutuhan_biologis_bab_keterangan" varchar(30) NOT NULL,
  "alergi_obat" varchar(15) NOT NULL CHECK ("alergi_obat" IN ('Tidak Ada', 'Tidak Diketahui', 'Ada')),
  "alergi_obat_keterangan" varchar(40) NOT NULL,
  "alergi_obat_reaksi" varchar(40) NOT NULL,
  "alergi_makanan" varchar(15) NOT NULL CHECK ("alergi_makanan" IN ('Tidak Ada', 'Tidak Diketahui', 'Ada')),
  "alergi_makanan_keterangan" varchar(40) NOT NULL,
  "alergi_makanan_reaksi" varchar(40) NOT NULL,
  "alergi_lainnya" varchar(15) NOT NULL CHECK ("alergi_lainnya" IN ('Tidak Ada', 'Tidak Diketahui', 'Ada')),
