  "penilaian_humptydumpty_skala5" varchar(46) NOT NULL CHECK ("penilaian_humptydumpty_skala5" IN ('Riwayat Jatuh Dari Tempat Tidur Saat Bayi/Anak', 'Pasien Menggunakan Alat Bantu/Box/Mebel', 'Pasien Berada Di Tempat Tidur', 'Di Luar Ruang Rawat')),
  "penilaian_humptydumpty_nilai5" smallint NOT NULL,
  "penilaian_humptydumpty_skala6" varchar(12) NOT NULL CHECK ("penilaian_humptydumpty_skala6" IN ('Dalam 24 Jam', 'Dalam 48 Jam', '> 48 Jam')),
  "penilaian_humptydumpty_nilai6" smallint NOT NULL,
  "penilaian_humptydumpty_skala7" varchar(186) NOT NULL CHECK ("penilaian_humptydumpty_skala7" IN ('Bermacam-macam Obat Yang Digunakan : Obat Sedative (Kecuali Pasien ICU Yang Menggunakan sedasi dan paralisis), Hipnotik, Barbiturat, Fenoti-Azin, Antidepresan, Laksans/Diuretika,Narkotik', 'Salah Satu Dari Pengobatan Di Atas', 'Pengobatan Lain')),
  "penilaian_humptydumpty_nilai7" smallint NOT NULL,
