  "skala_nips1" varchar(69) NOT NULL CHECK ("skala_nips1" IN ('Otot Relaks / Wajah Tenang / Ekspresi Netral', 'Meringis / Otot Wajah Tegang / Alis Berkerut (Ekspresi Wajah Negatif)')),
  "skala_nips1_nilai" varchar(1) NOT NULL CHECK ("skala_nips1_nilai" IN ('0', '1')),
  "skala_nips2" varchar(83) NOT NULL CHECK ("skala_nips2" IN ('Tenang / Tidak Menangis', 'Merengek / Mengerang Lemah Intermiten', 'Menangis Keras / Melengking Terus Menerus / Menangis Tanpa Suara Bila Bayi Intubasi')),
  "skala_nips2_nilai" varchar(1) NOT NULL CHECK ("skala_nips2_nilai" IN ('0', '1', '2')),
  "skala_nips3" varchar(95) NOT NULL CHECK ("skala_nips3" IN ('Relaks / Bernapas Biasa', 'Perubahan Napas / Tarikan Irreguler / Lebih Cepat Dibandingkan Biasa / Menahan Napas / Tersedak')),
  "skala_nips3_nilai" varchar(1) NOT NULL CHECK ("skala_nips3_nilai" IN ('0', '1')),
  "skala_nips4" varchar(56) NOT NULL CHECK ("skala_nips4" IN ('Relaks / Tidak Ada Kekakuan Otot / Gerakan Tungkai Biasa', 'Fleksi / Ekstensi Tegang Kaku')),
  "skala_nips4_nilai" varchar(1) NOT NULL CHECK ("skala_nips4_nilai" IN ('0', '1')),
  "skala_nips5" varchar(29) NOT NULL CHECK ("skala_nips5" IN ('Tenang / Tidur Lelap / Bangun', 'Gelisah')),
  "skala_nips5_nilai" varchar(1) NOT NULL CHECK ("skala_nips5_nilai" IN ('0', '1')),
