  "skala_nips_keterangan" varchar(18) NOT NULL CHECK ("skala_nips_keterangan" IN ('0 : Tidak Nyeri', '1-2 : Nyeri Ringan', '3-4 : Nyeri Sedang', '> 4 : Nyeri Hebat')),
  "informasi_perencanaan_pulang" varchar(5) NOT NULL CHECK ("informasi_perencanaan_pulang" IN ('Ya', 'Tidak')),
  "lama_ratarata" varchar(3) NOT NULL,
