  "keterangan_macam_persalinan" varchar(40),
  "indikasi_persalinan_operatif" varchar(21) CHECK ("indikasi_persalinan_operatif" IN ('Tidak Ada', 'Gawat Janin', 'SC Sebelumnya', 'Kala II Memanjang', 'Komplikasi Tali Pusat', 'Malposisi', 'Gawat Ibu', 'CPD', 'Lainnya')),
