  "kelainan_placenta" varchar(70),
  "keterangan_lainnya_riwayat_persalinan" varchar(150),
  "f1" varchar(1) NOT NULL,
  "u1" varchar(1) NOT NULL,
  "t1" varchar(1) NOT NULL,
  "r1" varchar(1) NOT NULL,
  "w1" varchar(1) NOT NULL,
  "n1" varchar(2) NOT NULL,
  "f5" varchar(1) NOT NULL,
  "u5" varchar(1) NOT NULL,
  "t5" varchar(1) NOT NULL,
  "r5" varchar(1) NOT NULL,
  "w5" varchar(1) NOT NULL,
  "n5" varchar(2) NOT NULL,
  "f10" varchar(1) NOT NULL,
  "u10" varchar(1) NOT NULL,
  "t10" varchar(1) NOT NULL,
  "r10" varchar(1) NOT NULL,
  "w10" varchar(1) NOT NULL,
  "n10" varchar(2) NOT NULL,
  "bblahir" varchar(5),
  "panjang_badan" varchar(5),
  "lingkar_kepala" varchar(5),
  "lingkar_dada" varchar(5),
  "resusitasi_saat_lahir" varchar(23) CHECK ("resusitasi_saat_lahir" IN ('Tidak', 'Rangsang Taktil', 'O2', 'Ventilasi Dengan Maskre', 'Ventilasi Dengan EET', 'Lainnya')),
  "keterangan_resusitasi_saat_lahir" varchar(70),
  "obat_diberikan_saat_lahir" varchar(150),
  "keterangan_lainnya_keadaan_bayi" varchar(150),
  "kondisi_umum" varchar(15) CHECK ("kondisi_umum" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_kondisi_umum" varchar(40),
  "kulit" varchar(15) CHECK ("kulit" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_kulit" varchar(40),
  "kepala" varchar(15) CHECK ("kepala" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_kepala" varchar(40),
  "leher" varchar(15) CHECK ("leher" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_leher" varchar(40),
  "mata" varchar(15) CHECK ("mata" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_mata" varchar(40),
  "hidung" varchar(15) CHECK ("hidung" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_hidung" varchar(40),
  "telinga" varchar(15) CHECK ("telinga" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_telinga" varchar(40),
  "dada" varchar(15) CHECK ("dada" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_dada" varchar(40),
  "paru" varchar(15) CHECK ("paru" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_paru" varchar(40),
  "jantung" varchar(15) CHECK ("jantung" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_jantung" varchar(40),
  "perut" varchar(15) CHECK ("perut" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_perut" varchar(40),
  "tali_pusat" varchar(15) CHECK ("tali_pusat" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_tali_pusat" varchar(40),
  "alat_kelamin" varchar(15) CHECK ("alat_kelamin" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_alat_kelamin" varchar(40),
  "ruas_tulang_belakang" varchar(15) CHECK ("ruas_tulang_belakang" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_ruas_tulang_belakang" varchar(40),
  "extrimitas" varchar(15) CHECK ("extrimitas" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_extrimitas" varchar(40),
  "anus" varchar(15) CHECK ("anus" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
