-- Tabel penilaian_dehidrasi
CREATE TABLE "penilaian_dehidrasi" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "penilaian1" varchar(37) CHECK ("penilaian1" IN ('Baik', 'Lesu/Haus', 'Gelisah, Haus, Mengantuk, Hingga Syok')),
  "penilaian_nilai1" smallint,
  "penilaian2" varchar(13) CHECK ("penilaian2" IN ('Biasa', 'Cekung', 'Sangat Cekung')),
  "penilaian_nilai2" smallint,
  "penilaian3" varchar(13) CHECK ("penilaian3" IN ('Biasa', 'Kering', 'Sangat Kering')),
  "penilaian_nilai3" smallint,
  "penilaian4" varchar(15) CHECK ("penilaian4" IN ('< 30 x/menit', '30 - 40 x/menit', '> 40 x/menit')),
  "penilaian_nilai4" smallint,
  "penilaian5" varchar(6) CHECK ("penilaian5" IN ('Baik', 'Kurang', 'Jelek')),
  "penilaian_nilai5" smallint,
  "penilaian6" varchar(17) CHECK ("penilaian6" IN ('< 120 x/menit', '120 - 140 x/menit', '> 140 x/menit')),
  "penilaian_nilai6" smallint,
  "penilaian_totalnilai" smallint,
  "hasil_penilaian" varchar(200),
  "kd_dokter" varchar(20) NOT NULL,
  CONSTRAINT "penilaian_dehidrasi_pkey" PRIMARY KEY ("no_rawat", "tanggal")
);

-- Tabel penilaian_fisioterapi
CREATE TABLE "penilaian_fisioterapi" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "informasi" varchar(13) NOT NULL CHECK ("informasi" IN ('Autoanamnesis', 'Alloanamnesis')),
  "keluhan_utama" varchar(150) DEFAULT '''''' NOT NULL,
  "rps" varchar(100) DEFAULT '''''' NOT NULL,
  "rpd" varchar(100) NOT NULL,
  "td" varchar(8) DEFAULT '' NOT NULL,
  "hr" varchar(5) DEFAULT '' NOT NULL,
  "rr" varchar(5) NOT NULL,
  "suhu" varchar(5) DEFAULT '' NOT NULL,
  "nyeri_tekan" varchar(5) NOT NULL,
  "nyeri_gerak" varchar(5) NOT NULL,
  "nyeri_diam" varchar(5) NOT NULL,
  "palpasi" varchar(50) NOT NULL,
  "luas_gerak_sendi" varchar(50) NOT NULL,
  "kekuatan_otot" varchar(50) NOT NULL,
  "statis" varchar(50) NOT NULL,
  "dinamis" varchar(50) NOT NULL,
  "kognitif" varchar(50) NOT NULL,
  "auskultasi" varchar(50) NOT NULL,
  "alat_bantu" varchar(5) NOT NULL CHECK ("alat_bantu" IN ('Tidak', 'Ya')),
  "ket_bantu" varchar(50) DEFAULT '' NOT NULL,
  "prothesa" varchar(5) NOT NULL CHECK ("prothesa" IN ('Tidak', 'Ya')),
  "ket_pro" varchar(50) NOT NULL,
  "deformitas" varchar(5) NOT NULL CHECK ("deformitas" IN ('Tidak', 'Ya')),
  "ket_deformitas" varchar(50) NOT NULL,
  "resikojatuh" varchar(5) NOT NULL CHECK ("resikojatuh" IN ('Tidak', 'Ya')),
  "ket_resikojatuh" varchar(50) NOT NULL,
  "adl" varchar(7) NOT NULL CHECK ("adl" IN ('Mandiri', 'Dibantu')),
  "lainlain_fungsional" varchar(70) NOT NULL,
  "ket_fisik" text NOT NULL,
  "pemeriksaan_musculoskeletal" varchar(200) NOT NULL,
  "pemeriksaan_neuromuscular" varchar(200) NOT NULL,
  "pemeriksaan_cardiopulmonal" varchar(200) NOT NULL,
  "pemeriksaan_integument" varchar(200) NOT NULL,
  "pengukuran_musculoskeletal" varchar(200) NOT NULL,
  "pengukuran_neuromuscular" varchar(200) NOT NULL,
  "pengukuran_cardiopulmonal" varchar(200) NOT NULL,
  "pengukuran_integument" varchar(200) NOT NULL,
  "penunjang" varchar(500) NOT NULL,
  "diagnosis_fisio" varchar(100) NOT NULL,
  "rencana_terapi" varchar(200) NOT NULL,
  "nip" varchar(20) NOT NULL,
  CONSTRAINT "penilaian_fisioterapi_pkey" PRIMARY KEY ("no_rawat")
);

-- Tabel penilaian_grace_scor
CREATE TABLE "penilaian_grace_scor" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "usia" smallint NOT NULL,
  "skor_usia" smallint NOT NULL,
  "denyut_jantung" integer NOT NULL,
  "skor_denyut_jantung" smallint NOT NULL,
  "sistolik" integer NOT NULL,
  "skor_sistolik" smallint NOT NULL,
  "kreatinin" numeric(4,2) NOT NULL,
  "skor_kreatinin" smallint NOT NULL,
  "killip" varchar(3) NOT NULL CHECK ("killip" IN ('I', 'II', 'III', 'IV')),
  "skor_killip" smallint NOT NULL,
  "deviasi_st" varchar(5) NOT NULL CHECK ("deviasi_st" IN ('Tidak', 'Ya')),
  "skor_deviasi_st" smallint NOT NULL,
  "troponin" varchar(5) NOT NULL CHECK ("troponin" IN ('Tidak', 'Ya')),
  "skor_troponin" smallint NOT NULL,
  "henti_jantung" varchar(5) NOT NULL CHECK ("henti_jantung" IN ('Tidak', 'Ya')),
  "skor_henti_jantung" smallint NOT NULL,
  "skor" integer NOT NULL,
  "kategori" varchar(17) NOT NULL CHECK ("kategori" IN ('Low Risk', 'Intermediate Risk', 'High Risk')),
  "keterangan" varchar(255),
  "kd_dokter" varchar(20) NOT NULL,
  CONSTRAINT "penilaian_grace_scor_pkey" PRIMARY KEY ("no_rawat")
);

-- Tabel penilaian_korban_kekerasan
CREATE TABLE "penilaian_korban_kekerasan" (
