  "penilaian_jatuhmorse_nilai5" smallint,
  "penilaian_jatuhmorse_skala6" varchar(31) CHECK ("penilaian_jatuhmorse_skala6" IN ('Mandiri', 'Berjalan Dengan Bantuan 1 Orang', 'Menggunakan Kursi Roda', 'Imobilisasi')),
  "penilaian_jatuhmorse_nilai6" smallint,
  "penilaian_jatuhmorse_totalnilai" smallint,
  "hasil_skrining" varchar(200),
  "saran" varchar(200),
  "nip" varchar(20) NOT NULL,
  CONSTRAINT "penilaian_lanjutan_resiko_jatuh_lansia_pkey" PRIMARY KEY ("no_rawat", "tanggal")
);

-- Tabel penilaian_lanjutan_resiko_jatuh_psikiatri
CREATE TABLE "penilaian_lanjutan_resiko_jatuh_psikiatri" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "penilaian_jatuhedmonson_skala1" varchar(17) CHECK ("penilaian_jatuhedmonson_skala1" IN ('-', 'Kurang Dari 50 Th', '50 - 70 Th', 'Lebih Dari 70 Th')),
  "penilaian_jatuhedmonson_nilai1" smallint,
  "penilaian_jatuhedmonson_skala2" varchar(36) CHECK ("penilaian_jatuhedmonson_skala2" IN ('-', 'Kesadaran/Orientasi Baik Setiap Saat', 'Agitasi/Ansietas', 'Kadang-kadang Bingung', 'Bingung/Disorientasi')),
  "penilaian_jatuhedmonson_nilai2" smallint,
  "penilaian_jatuhedmonson_skala3" varchar(53) CHECK ("penilaian_jatuhedmonson_skala3" IN ('-', 'Mandiri & Mampu Mengontrol BAB/BAK', 'Dower Catheter/Colostomy', 'Eliminasi Dengan Bantuan', 'Gangguan Eliminasi (Inkontinensia/Nokturia/Frekuensi)', 'Inkontinensia Tetapi Mampu Untuk Mobilisasi')),
  "penilaian_jatuhedmonson_nilai3" smallint,
  "penilaian_jatuhedmonson_skala4" varchar(68) CHECK ("penilaian_jatuhedmonson_skala4" IN ('-', 'Tanpa Obat-obatan', 'Obat-obatan Jantung', 'Obat-obatan Psikotropika (Termasuk Benzodiazepine & Antidepresan)', 'Mendapat Tambahan Obat-obatan & Atau Obat PRN Selama 24 Jam Terakhir')),
  "penilaian_jatuhedmonson_nilai4" smallint,
  "penilaian_jatuhedmonson_skala5" varchar(56) CHECK ("penilaian_jatuhedmonson_skala5" IN ('-', 'Bipolar/Gangguan Schizoaffective', 'Penggunaan Obat-obatan Terlarang, Ketergantungan Alkohol', 'Gangguan Depresi Mayor', 'Demensia/Delirium')),
  "penilaian_jatuhedmonson_nilai5" smallint,
  "penilaian_jatuhedmonson_skala6" varchar(47) CHECK ("penilaian_jatuhedmonson_skala6" IN ('-', 'Mandiri/Keseimbangan Baik/Imobilisasi', 'Dengan Alat Bantu (Kursi Roda, Walker, Dll)', 'Vertigo/Kelemahan', 'Goyah/Membutuhkan Bantuan & Menyadari Kemampuan', 'Goyah Tapi Lupa Keterbatasan')),
  "penilaian_jatuhedmonson_nilai6" smallint,
  "penilaian_jatuhedmonson_totalnilai" smallint,
  "hasil_skrining" varchar(200),
  "saran" varchar(200),
  "nip" varchar(20) NOT NULL,
  CONSTRAINT "penilaian_lanjutan_resiko_jatuh_psikiatri_pkey" PRIMARY KEY ("no_rawat", "tanggal")
);

