  "penilaian_skrining_nilai5" smallint,
  "penilaian_skrining_skala6" varchar(47) CHECK ("penilaian_skrining_skala6" IN ('Tidak Mampu', 'Perlu Banyak Bantuan Untuk Bisa Duduk (2 Orang)', 'Bantuan Minimal 1 Orang', 'Mandiri')),
  "penilaian_skrining_nilai6" smallint,
  "penilaian_skrining_skala7" varchar(31) CHECK ("penilaian_skrining_skala7" IN ('Tidak Mampu', 'Bisa (Pindah) Dengan Kursi Roda', 'Berjalan Dengan Bantuan 1 Orang', 'Mandiri')),
  "penilaian_skrining_nilai7" smallint,
  "penilaian_skrining_skala8" varchar(40) CHECK ("penilaian_skrining_skala8" IN ('Tergantung Orang Lain', 'Sebagian Dibantu (Misal Mengancing Baju)', 'Mandiri')),
  "penilaian_skrining_nilai8" smallint,
  "penilaian_skrining_skala9" varchar(17) CHECK ("penilaian_skrining_skala9" IN ('Tidak Mampu', 'Butuh Pertolongan', 'Mandiri')),
  "penilaian_skrining_nilai9" smallint,
  "penilaian_skrining_skala10" varchar(21) CHECK ("penilaian_skrining_skala10" IN ('Tergantung Orang Lain', 'Mandiri')),
  "penilaian_skrining_nilai10" smallint,
  "penilaian_skrining_totalnilai" smallint,
  "nip" varchar(20) NOT NULL,
  CONSTRAINT "penilaian_lanjutan_skrining_fungsional_pkey" PRIMARY KEY ("no_rawat", "tanggal")
);

