-- Tabel penilaian_mcu
CREATE TABLE "penilaian_mcu" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "kd_dokter" varchar(20) NOT NULL,
  "informasi" varchar(13) NOT NULL CHECK ("informasi" IN ('Autoanamnesis', 'Alloanamnesis')),
  "rps" varchar(2000) NOT NULL,
  "rpk" varchar(1000) NOT NULL,
  "rpd" varchar(1000) NOT NULL,
  "alergi" varchar(150) DEFAULT '' NOT NULL,
  "keadaan" varchar(10) NOT NULL CHECK ("keadaan" IN ('Baik', 'Tidak Baik')),
  "kesadaran" varchar(12) NOT NULL CHECK ("kesadaran" IN ('Composmentis', 'Apatis', 'Somnolen')),
  "td" varchar(8) DEFAULT '' NOT NULL,
  "nadi" varchar(5) DEFAULT '' NOT NULL,
  "rr" varchar(5) NOT NULL,
  "tb" varchar(5) DEFAULT '' NOT NULL,
  "bb" varchar(5) DEFAULT '' NOT NULL,
  "suhu" varchar(5) DEFAULT '' NOT NULL,
  "bmi" varchar(6) NOT NULL,
  "kasifikasi_bmi" varchar(21) NOT NULL CHECK ("kasifikasi_bmi" IN ('Berat Badan Kurang', 'Berat Badan Normal', 'Kelebihan Berat Badan', 'Obesitas I', 'Obesitas II')),
  "lingkar_pinggang" varchar(6) NOT NULL,
  "risiko_lingkar_pinggang" varchar(9) NOT NULL CHECK ("risiko_lingkar_pinggang" IN ('Rendah', 'Cukup', 'Meningkat', 'Moderat', 'Berat', 'Sangat')),
  "submandibula" varchar(14) NOT NULL CHECK ("submandibula" IN ('Tidak Membesar', 'Membesar', '-')),
  "axilla" varchar(14) NOT NULL CHECK ("axilla" IN ('Tidak Membesar', 'Membesar', '-')),
  "supraklavikula" varchar(14) NOT NULL CHECK ("supraklavikula" IN ('Tidak Membesar', 'Membesar', '-')),
  "leher" varchar(14) NOT NULL CHECK ("leher" IN ('Tidak Membesar', 'Membesar', '-')),
  "inguinal" varchar(14) NOT NULL CHECK ("inguinal" IN ('Tidak Membesar', 'Membesar', '-')),
  "oedema" varchar(9) NOT NULL CHECK ("oedema" IN ('Tidak Ada', 'Ada', '-')),
  "sinus_frontalis" varchar(9) NOT NULL CHECK ("sinus_frontalis" IN ('Tidak Ada', 'Ada', '=')),
  "sinus_maxilaris" varchar(9) NOT NULL CHECK ("sinus_maxilaris" IN ('Tidak Ada', 'Ada', '-')),
  "rambut" varchar(100) NOT NULL,
  "palpebra" varchar(6) NOT NULL CHECK ("palpebra" IN ('Normal', 'Oedem', 'Ptosis', '-')),
  "sklera" varchar(7) NOT NULL CHECK ("sklera" IN ('Normal', 'Ikterik', '-')),
  "cornea" varchar(12) NOT NULL CHECK ("cornea" IN ('Normal', 'Tidak Normal', '-')),
  "buta_warna" varchar(18) NOT NULL CHECK ("buta_warna" IN ('Normal', 'Buta Warna Partial', 'Buta Warna Total', '-')),
  "konjungtiva" varchar(9) NOT NULL CHECK ("konjungtiva" IN ('Normal', 'Anemis', 'Hiperemis', '-')),
  "lensa" varchar(8) NOT NULL CHECK ("lensa" IN ('Jernih', 'Keruh', 'Kacamata', '-')),
  "pupil" varchar(8) NOT NULL CHECK ("pupil" IN ('Isokor', 'Anisokor', '-')),
  "menggunakan_kacamata" varchar(5) NOT NULL CHECK ("menggunakan_kacamata" IN ('Tidak', 'Ya', '-')),
  "visus" varchar(50) NOT NULL,
  "luas_lapang_pandang" varchar(12) NOT NULL CHECK ("luas_lapang_pandang" IN ('Normal', 'Tidak Normal', '-')),
  "keterangan_luas_lapang_pandang" varchar(50) NOT NULL,
  "lubang_telinga" varchar(12) NOT NULL CHECK ("lubang_telinga" IN ('Normal', 'Tidak Normal', 'Lapang', 'Sempit', 'Serumen Prop', '-')),
  "daun_telinga" varchar(12) NOT NULL CHECK ("daun_telinga" IN ('Normal', 'Tidak Normal', '-')),
  "selaput_pendengaran" varchar(11) NOT NULL CHECK ("selaput_pendengaran" IN ('Intak', 'Tidak Intak', '-')),
  "proc_mastoideus" varchar(12) NOT NULL CHECK ("proc_mastoideus" IN ('Normal', 'Tidak Normal', '-')),
  "septum_nasi" varchar(7) NOT NULL CHECK ("septum_nasi" IN ('Normal', 'Deviasi', '-')),
  "lubang_hidung" varchar(10) NOT NULL CHECK ("lubang_hidung" IN ('Lapang', 'Rhinore', 'Epistaksis', '-')),
  "sinus" varchar(12) NOT NULL CHECK ("sinus" IN ('Normal', 'Tidak Normal', '-')),
  "bibir" varchar(6) NOT NULL CHECK ("bibir" IN ('Lembab', 'Kering')),
  "gusi" varchar(12) NOT NULL CHECK ("gusi" IN ('Normal', 'Tidak Normal', '-')),
  "gigi" varchar(12) NOT NULL CHECK ("gigi" IN ('Normal', 'Tidak Normal', '-')),
  "caries" varchar(9) NOT NULL CHECK ("caries" IN ('Tidak Ada', 'Ada', '-')),
  "lidah" varchar(6) NOT NULL CHECK ("lidah" IN ('Bersih', 'Kotor', 'Tremor', '-')),
  "faring" varchar(9) NOT NULL CHECK ("faring" IN ('Normal', 'Hiperemis', '-')),
  "tonsil" varchar(5) NOT NULL CHECK ("tonsil" IN ('T1-T1', 'T2-T2', 'T3-T3', 'T4-T4', 'T0-T0', '-')),
  "kelenjar_limfe" varchar(14) NOT NULL CHECK ("kelenjar_limfe" IN ('Tidak Membesar', 'Membesar', '-')),
  "kelenjar_gondok" varchar(14) NOT NULL CHECK ("kelenjar_gondok" IN ('Tidak Membesar', 'Membesar', '-')),
  "gerakan_dada" varchar(14) NOT NULL CHECK ("gerakan_dada" IN ('Simetris', 'Tidak Simetris', '-')),
  "vocal_femitus" varchar(10) NOT NULL CHECK ("vocal_femitus" IN ('Sama', 'Tidak Sama', '-')),
  "perkusi_dada" varchar(5) NOT NULL CHECK ("perkusi_dada" IN ('Sonor', 'Pekak', '-')),
  "bunyi_napas" varchar(9) NOT NULL CHECK ("bunyi_napas" IN ('Vesikuler', 'Bronkhial', 'Trakeal', '-')),
  "bunyi_tambahan" varchar(9) NOT NULL CHECK ("bunyi_tambahan" IN ('Tidak Ada', 'Wheezing', 'Ronchi', '-')),
  "ictus_cordis" varchar(14) NOT NULL CHECK ("ictus_cordis" IN ('Tidak Terlihat', 'Terlihat', ' Teraba', 'Tidak Teraba', '-')),
  "bunyi_jantung" varchar(9) NOT NULL CHECK ("bunyi_jantung" IN ('Reguler', 'Irreguler', 'Gallop', 'Lain-lain', '-')),
  "batas" varchar(7) NOT NULL CHECK ("batas" IN ('Normal', 'Melebar', '-')),
  "mamae" varchar(12) NOT NULL CHECK ("mamae" IN ('Normal', 'Tidak Normal', '-')),
  "keterangan_mamae" varchar(100) NOT NULL,
  "inspeksi" varchar(7) NOT NULL CHECK ("inspeksi" IN ('Datar', 'Cembung', '-')),
  "palpasi" varchar(32) NOT NULL CHECK ("palpasi" IN ('Supel', 'Tegang (Defans Muscular)', 'Nyeri Tekan Epigastrium', 'Nyeri Tekan Suprapubik', 'Nyeri Tekan Right Lower Quadrant', 'Nyeri Tekan Left Lower Quadrant', '-')),
  "hepar" varchar(14) NOT NULL CHECK ("hepar" IN ('Tidak Membesar', 'Membesar', '-')),
  "perkusi_abdomen" varchar(12) NOT NULL CHECK ("perkusi_abdomen" IN ('Timpani', 'Hipertimpani', 'Dull', '-')),
  "auskultasi" varchar(21) NOT NULL CHECK ("auskultasi" IN ('Normal', 'Bising Usus Meningkat', 'Bising Usus Menurun', '-')),
  "limpa" varchar(14) NOT NULL CHECK ("limpa" IN ('Tidak Membesar', 'Membesar', '-')),
  "costovertebral" varchar(12) NOT NULL CHECK ("costovertebral" IN ('Tidak Ada', 'Ada Di Kiri', 'Ada Di Kanan', '-')),
  "scoliosis" varchar(9) NOT NULL CHECK ("scoliosis" IN ('Tidak Ada', 'Ada', '-')),
  "kondisi_kulit" varchar(14) NOT NULL CHECK ("kondisi_kulit" IN ('Normal', 'Tato', 'Penyakit Kulit', '-')),
  "penyakit_kulit" varchar(100) NOT NULL,
  "ekstrimitas_atas" varchar(12) NOT NULL CHECK ("ekstrimitas_atas" IN ('Normal', 'Tidak Normal', '-')),
  "ekstrimitas_atas_ket" varchar(50) NOT NULL,
  "ekstrimitas_bawah" varchar(12) NOT NULL CHECK ("ekstrimitas_bawah" IN ('Normal', 'Tidak Normal', '-')),
  "ekstrimitas_bawah_ket" varchar(50) NOT NULL,
  "area_genitalia" varchar(18) NOT NULL CHECK ("area_genitalia" IN ('Tidak Ada Kelainan', 'Ada Kelainan', '-')),
  "keterangan_area_genitalia" varchar(100) NOT NULL,
  "anus_perianal" varchar(12) NOT NULL CHECK ("anus_perianal" IN ('Normal', 'Tidak Normal', '-')),
  "keterangan_anus_perianal" varchar(100) NOT NULL,
  "laborat" text NOT NULL,
  "radiologi" text NOT NULL,
  "ekg" text NOT NULL,
  "spirometri" text NOT NULL,
  "audiometri" text NOT NULL,
  "treadmill" text NOT NULL,
  "romberg_test" text NOT NULL,
  "back_strength" text NOT NULL,
  "abi_tangan_kanan" text NOT NULL,
  "abi_tangan_kiri" text NOT NULL,
  "abi_kaki_kanan" text NOT NULL,
  "abi_kaki_kiri" text NOT NULL,
  "lainlain" text NOT NULL,
  "merokok" varchar(100) NOT NULL,
  "alkohol" varchar(100) NOT NULL,
  "kesimpulan" text NOT NULL,
  "anjuran" text NOT NULL,
  CONSTRAINT "penilaian_mcu_pkey" PRIMARY KEY ("no_rawat")
);

-- Tabel penilaian_medis_hemodialisa
CREATE TABLE "penilaian_medis_hemodialisa" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp,
  "kd_dokter" varchar(20),
  "anamnesis" varchar(13) CHECK ("anamnesis" IN ('Autoanamnesis', 'Alloanamnesis')),
  "hubungan" varchar(30),
  "ruangan" varchar(50),
  "alergi" varchar(100),
  "nyeri" varchar(21) CHECK ("nyeri" IN ('Tidak Nyeri', 'Nyeri Ringan', 'Nyeri Sedang', 'Nyeri Berat', 'Nyeri Sangat Berat', 'Nyeri Tak Tertahankan')),
  "status_nutrisi" varchar(100),
  "hipertensi" varchar(5) CHECK ("hipertensi" IN ('Tidak', 'Ya')),
  "keterangan_hipertensi" varchar(30),
  "diabetes" varchar(5) CHECK ("diabetes" IN ('Tidak', 'Ya')),
  "keterangan_diabetes" varchar(30),
  "batu_saluran_kemih" varchar(5) CHECK ("batu_saluran_kemih" IN ('Tidak', 'Ya')),
  "keterangan_batu_saluran_kemih" varchar(30),
  "operasi_saluran_kemih" varchar(5) CHECK ("operasi_saluran_kemih" IN ('Tidak', 'Ya')),
  "keterangan_operasi_saluran_kemih" varchar(30),
  "infeksi_saluran_kemih" varchar(5) CHECK ("infeksi_saluran_kemih" IN ('Tidak', 'Ya')),
  "keterangan_infeksi_saluran_kemih" varchar(30),
  "bengkak_seluruh_tubuh" varchar(5) CHECK ("bengkak_seluruh_tubuh" IN ('Tidak', 'Ya')),
  "keterangan_bengkak_seluruh_tubuh" varchar(30),
  "urin_berdarah" varchar(5) CHECK ("urin_berdarah" IN ('Tidak', 'Ya')),
  "keterangan_urin_berdarah" varchar(30),
  "penyakit_ginjal_laom" varchar(5) CHECK ("penyakit_ginjal_laom" IN ('Tidak', 'Ya')),
  "keterangan_penyakit_ginjal_laom" varchar(30),
  "penyakit_lain" varchar(5) CHECK ("penyakit_lain" IN ('Tidak', 'Ya')),
  "keterangan_penyakit_lain" varchar(30),
  "konsumsi_obat_nefro" varchar(5) CHECK ("konsumsi_obat_nefro" IN ('Tidak', 'Ya')),
  "keterangan_konsumsi_obat_nefro" varchar(30),
  "dialisis_pertama" date NOT NULL,
  "pernah_cpad" varchar(5) NOT NULL CHECK ("pernah_cpad" IN ('Tidak', 'Ya')),
  "tanggal_cpad" date NOT NULL,
  "pernah_transplantasi" varchar(5) NOT NULL CHECK ("pernah_transplantasi" IN ('Tidak', 'Ya')),
  "tanggal_transplantasi" date NOT NULL,
  "keadaan_umum" varchar(12) NOT NULL CHECK ("keadaan_umum" IN ('Sehat', 'Sakit Ringan', 'Sakit Sedang', 'Sakit Berat')),
  "kesadaran" varchar(13) NOT NULL CHECK ("kesadaran" IN ('Compos Mentis', 'Apatis', 'Somnolen', 'Sopor', 'Koma')),
  "nadi" varchar(5) NOT NULL,
  "bb" varchar(5) NOT NULL,
  "td" varchar(8) NOT NULL,
  "suhu" varchar(5) NOT NULL,
  "napas" varchar(5) NOT NULL,
  "tb" varchar(5) NOT NULL,
  "hepatomegali" varchar(5) NOT NULL CHECK ("hepatomegali" IN ('Tidak', 'Ya')),
  "splenomegali" varchar(5) NOT NULL CHECK ("splenomegali" IN ('Tidak', 'Ya')),
  "ascites" varchar(5) NOT NULL CHECK ("ascites" IN ('Tidak', 'Ya')),
  "edema" varchar(5) NOT NULL CHECK ("edema" IN ('Tidak', 'Ya')),
