  "thoraks" varchar(15) NOT NULL CHECK ("thoraks" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_thoraks" varchar(100) NOT NULL,
  "abdomen" varchar(15) NOT NULL CHECK ("abdomen" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_abdomen" varchar(100) NOT NULL,
  "ekstremitas" varchar(15) NOT NULL CHECK ("ekstremitas" IN ('Normal', 'Abnormal', 'Tidak Diperiksa')),
  "keterangan_ekstremitas" varchar(100) NOT NULL,
  "integument_kebersihan" varchar(8) NOT NULL CHECK ("integument_kebersihan" IN ('Normal', 'Abnormal')),
  "integument_warna" varchar(9) NOT NULL CHECK ("integument_warna" IN ('Normal', 'Pucat', 'Sianosis', 'Lain-lain')),
  "integument_kelembaban" varchar(6) NOT NULL CHECK ("integument_kelembaban" IN ('Kering', 'Lembab')),
  "integument_gangguan_kulit" varchar(6) NOT NULL CHECK ("integument_gangguan_kulit" IN ('Normal', 'Rash', 'Luka', 'Memar', 'Ptekie', 'Bula')),
  "status_fungsional" varchar(33) NOT NULL CHECK ("status_fungsional" IN ('20 : Mandiri (A)', '12-19 : Ketergantungan Ringan (B)', '9-11 : Ketergantungan Sedang (B)', '5-8 : Ketergantungan Berat (C)', '0-4 : Ketergantungan Total (C)')),
  "skrining_jatuh" varchar(24) NOT NULL CHECK ("skrining_jatuh" IN ('Risiko Rendah Skor 0-5', 'Risiko Sedang Skor 6-16', 'Risiko Tinggi Skor 17-30')),
  "status_nutrisi" varchar(31) NOT NULL CHECK ("status_nutrisi" IN ('Skor 12-14 : Status Gizi Normal', 'Skor 8-11 : Berisiko Malnutrisi', 'Skor 0-7 : Malnutrisi')),
  "lainnya" varchar(1000) NOT NULL,
  "lab" varchar(500) NOT NULL,
  "rad" varchar(500) NOT NULL,
  "pemeriksaan" varchar(500) NOT NULL,
  "diagnosis" varchar(500) NOT NULL,
  "diagnosis2" varchar(500) NOT NULL,
  "permasalahan" varchar(500) NOT NULL,
  "terapi" varchar(500) NOT NULL,
  "tindakan" varchar(500) NOT NULL,
  "edukasi" varchar(500) NOT NULL,
  CONSTRAINT "penilaian_medis_ralan_geriatri_pkey" PRIMARY KEY ("no_rawat")
);

