  "status_mental" varchar(7) CHECK ("status_mental" IN ('Sadar', 'Apatis', 'Bingung', 'Stupor')),
  "status_mental_nilai" smallint,
  "aktifitas" varchar(20) CHECK ("aktifitas" IN ('Jalan Sendiri', 'Jalan Dengan Bantuan', 'Kursi Roda', 'Di Tempat Tidur')),
  "aktifitas_nilai" smallint,
  "mobilitas" varchar(20) CHECK ("mobilitas" IN ('Bebas Bergerak', 'Agar Terbatas', 'Sangat Terbatas', 'Tidak Mampu Bergerak')),
  "mobilitas_nilai" smallint,
  "inkontinensia" varchar(33) CHECK ("inkontinensia" IN ('Kontinen', 'Kadang-kadang Inkontinensia Urine', 'Selalu Inkontenesia Urine', 'Inkontinensia Alvi Dan Urine')),
  "inkontinensia_nilai" smallint,
  "totalnilai" smallint,
  "kategorinilai" varchar(13) CHECK ("kategorinilai" IN ('Risiko Rendah', 'Risiko Sedang', 'Risiko Tinggi')),
  "nip" varchar(20) NOT NULL,
  CONSTRAINT "penilaian_risiko_dekubitus_pkey" PRIMARY KEY ("no_rawat", "tanggal")
);

