-- Tabel penilaian_tambahan_geriatri
CREATE TABLE "penilaian_tambahan_geriatri" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "nik" varchar(20) NOT NULL,
  "asal_masuk" varchar(14) CHECK ("asal_masuk" IN ('IGD', 'Kamar Bersalin', 'Klinik')),
  "kondisi_masuk" varchar(12) CHECK ("kondisi_masuk" IN ('Mandiri', 'Kursi Roda', 'Dipapah', 'Tempat Tidur')),
  "keterangan_kondisi_masuk" varchar(50),
  "anamnesis" varchar(13) NOT NULL CHECK ("anamnesis" IN ('Autoanamnesis', 'Alloanamnesis')),
  "diagnosa_medis" varchar(100),
  "riwayat_immuno_telinga" varchar(5) CHECK ("riwayat_immuno_telinga" IN ('Ya', 'Tidak')),
  "riwayat_immuno_sinus" varchar(5) CHECK ("riwayat_immuno_sinus" IN ('Ya', 'Tidak')),
  "riwayat_immuno_antibiotik" varchar(5) CHECK ("riwayat_immuno_antibiotik" IN ('Ya', 'Tidak')),
  "riwayat_immuno_pneumonia" varchar(5) CHECK ("riwayat_immuno_pneumonia" IN ('Ya', 'Tidak')),
  "riwayat_immuno_abses" varchar(5) CHECK ("riwayat_immuno_abses" IN ('Ya', 'Tidak')),
  "riwayat_immuno_sariawan" varchar(5) CHECK ("riwayat_immuno_sariawan" IN ('Ya', 'Tidak')),
  "riwayat_immuno_memerlukan_antibiotik" varchar(5) CHECK ("riwayat_immuno_memerlukan_antibiotik" IN ('Ya', 'Tidak')),
  "riwayat_immuno_infeksi_dalam" varchar(5) CHECK ("riwayat_immuno_infeksi_dalam" IN ('Ya', 'Tidak')),
  "riwayat_immuno_immunodefisiensi_primer" varchar(5) CHECK ("riwayat_immuno_immunodefisiensi_primer" IN ('Ya', 'Tidak')),
  "riwayat_immuno_jenis_kangker" varchar(5) CHECK ("riwayat_immuno_jenis_kangker" IN ('Ya', 'Tidak')),
  "riwayat_immuno_infeksi_oportunistik" varchar(5) CHECK ("riwayat_immuno_infeksi_oportunistik" IN ('Ya', 'Tidak')),
  "pola_aktifitas_tidur" varchar(8) CHECK ("pola_aktifitas_tidur" IN ('TAK', 'Insomnia', 'Lainnya')),
  "keterangan_pola_aktifitas_tidur" varchar(50),
  "pola_aktifitas_obat_tidur" varchar(5) CHECK ("pola_aktifitas_obat_tidur" IN ('Tidak', 'Ya')),
  "keterangan_pola_aktifitas_obat_tidur" varchar(50),
  "pola_aktifitas_olahraga" varchar(5) CHECK ("pola_aktifitas_olahraga" IN ('Tidak', 'Ya')),
  "keterangan_pola_aktifitas_olahraga" varchar(50),
  "kualitas_hidup_mobilitas" varchar(38) CHECK ("kualitas_hidup_mobilitas" IN ('Tidak Mempunyai Masalah Untuk Berjalan', 'Ada Masalah Untuk Berjalan', 'Hanya Mampu Berbaring')),
  "kualitas_hidup_perawatan_diri" varchar(63) CHECK ("kualitas_hidup_perawatan_diri" IN ('Tidak Mempunyai Kesulitan Dalam Perawatan Diri Sendiri', 'Mengalami Kesulitan Untuk Membasuh Badan, Mandi Atau Berpakaian', 'Tidak Mampu Membasuh Badan, Mandi/Berpakaian Sendiri')),
  "kualitas_hidup_aktifitas_seharihari" varchar(63) CHECK ("kualitas_hidup_aktifitas_seharihari" IN ('Tak Mempunyai Kesulitan Dalam Melaksanakan Kegiatan Sehari-hari', 'Mempunyai Keterbatasan Dalam Melaksanakan Kegiatan Sehari-hari', 'Tak Mampu Melaksanakan Kegiatan Sehari-hari')),
  "kualitas_hidup_rasa_nyeri" varchar(55) CHECK ("kualitas_hidup_rasa_nyeri" IN ('Tidak Mempunyai Keluhan Rasa Nyeri Atau Rasa Tak Nyaman', 'Suka Merasakan Agak Nyeri/Agak Kurang Nyaman', 'Menderita Karena Keluhan Rasa Nyeri/Tidak Nyaman')),
  "skala_nyeri" varchar(77) CHECK ("skala_nyeri" IN ('0 - Tidak Nyeri', '2 - Dapat Ditoleransi(Aktifitas Tidak Tergangu)', '4 - Dapat Ditoleransi(Beberapa Aktifitas Sedikit Terganggu)', '5 - Tidak Dapat Ditoleransi(Masih Bisa Menggunakan Telp, Menonton TV/Membaca)', '6 - Tidak Dapat Ditoleransi(Tidak Bisa Menggunakan Telp, Menonton TV/Membaca)', '8 - Tidak Dapat Ditoleransi(Masih Bisa Berbicara Kerenya Nyeri)', '10 - Tidak Dapat Ditoleransi(Tidak Bisa Berbicara Kerenya Nyeri)')),
  CONSTRAINT "penilaian_tambahan_geriatri_pkey" PRIMARY KEY ("no_rawat")
);

