-- Tabel persetujuan_penolakan_tindakan
CREATE TABLE "persetujuan_penolakan_tindakan" (
  "no_pernyataan" varchar(20) NOT NULL,
  "no_rawat" varchar(17),
  "tanggal" date,
  "diagnosa" varchar(200),
  "diagnosa_konfirmasi" varchar(5) CHECK ("diagnosa_konfirmasi" IN ('true', 'false')),
  "tindakan" varchar(200),
  "tindakan_konfirmasi" varchar(5) CHECK ("tindakan_konfirmasi" IN ('true', 'false')),
  "indikasi_tindakan" varchar(200),
  "indikasi_tindakan_konfirmasi" varchar(5) CHECK ("indikasi_tindakan_konfirmasi" IN ('true', 'false')),
  "tata_cara" varchar(400),
  "tata_cara_konfirmasi" varchar(5) CHECK ("tata_cara_konfirmasi" IN ('true', 'false')),
  "tujuan" varchar(200),
  "tujuan_konfirmasi" varchar(5) CHECK ("tujuan_konfirmasi" IN ('true', 'false')),
  "risiko" varchar(200),
  "risiko_konfirmasi" varchar(5) CHECK ("risiko_konfirmasi" IN ('true', 'false')),
  "komplikasi" varchar(200),
  "komplikasi_konfirmasi" varchar(5) CHECK ("komplikasi_konfirmasi" IN ('true', 'false')),
  "prognosis" varchar(200),
  "prognosis_konfirmasi" varchar(5) CHECK ("prognosis_konfirmasi" IN ('true', 'false')),
  "alternatif_dan_risikonya" varchar(200),
  "alternatif_konfirmasi" varchar(5) CHECK ("alternatif_konfirmasi" IN ('true', 'false')),
  "biaya" double precision,
  "biaya_konfirmasi" varchar(5) CHECK ("biaya_konfirmasi" IN ('true', 'false')),
  "lain_lain" varchar(200),
  "lain_lain_konfirmasi" varchar(5) CHECK ("lain_lain_konfirmasi" IN ('true', 'false')),
  "kd_dokter" varchar(20) NOT NULL,
  "nip" varchar(20) NOT NULL,
  "penerima_informasi" varchar(50) NOT NULL,
  "alasan_diwakilkan_penerima_informasi" varchar(40) NOT NULL,
  "jk_penerima_informasi" varchar(1) NOT NULL CHECK ("jk_penerima_informasi" IN ('L', 'P')),
  "tanggal_lahir_penerima_informasi" date NOT NULL,
  "umur_penerima_informasi" varchar(30) NOT NULL,
  "alamat_penerima_informasi" varchar(100) NOT NULL,
  "no_hp" varchar(40) NOT NULL,
  "hubungan_penerima_informasi" varchar(15) NOT NULL CHECK ("hubungan_penerima_informasi" IN ('Diri Sendiri', 'Orang Tua', 'Anak', 'Saudara Kandung', 'Teman', 'Lain-lain')),
  "pernyataan" varchar(18) NOT NULL CHECK ("pernyataan" IN ('Belum Dikonfirmasi', 'Persetujuan', 'Penolakan')),
  "saksi_keluarga" varchar(50) NOT NULL,
  CONSTRAINT "persetujuan_penolakan_tindakan_pkey" PRIMARY KEY ("no_pernyataan")
);

-- Tabel persetujuan_penundaan_pelayanan
