  "keterangan_ditunda" varchar(50),
  "alternatif_diberikan" varchar(35) CHECK ("alternatif_diberikan" IN ('Dijadwalkan Ulang', 'Dirujuk Ke Layanan Kesehatan Lain', 'Dikembalikan Kepada Dokter Pengirim', 'Lain-lain')),
  "keterangan_alternatif_diberikan" varchar(50) NOT NULL,
  "nip" varchar(20) NOT NULL,
