  "jam_datang" timestamp NOT NULL,
  "jam_pulang" timestamp,
  "status" varchar(25) NOT NULL CHECK ("status" IN ('Tepat Waktu', 'Terlambat Toleransi', 'Terlambat I', 'Terlambat II', 'Tepat Waktu & PSW', 'Terlambat Toleransi & PSW', 'Terlambat I & PSW', 'Terlambat II & PSW')),
  "keterlambatan" varchar(20) NOT NULL,
  "durasi" varchar(20),
  "keterangan" varchar(100) NOT NULL,
  "photo" varchar(500) NOT NULL,
  CONSTRAINT "rekap_presensi_pkey" PRIMARY KEY ("id", "jam_datang")
);

