  "kelas_ruang_siranap" varchar(21) NOT NULL CHECK ("kelas_ruang_siranap" IN ('0001 Super VIP', '0002 VIP', '0003 Kelas 1', '0004 Kelas 2', '0005 Kelas 3', '0006 Intermediate', '0007 Isolasi', '0008 Rawat Khusus', '0009 Stroke Care Unit')),
  "kd_bangsal" varchar(5) DEFAULT '' NOT NULL,
