  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "penilaian_skala1" varchar(47) CHECK ("penilaian_skala1" IN ('Tidak Sanggup Menggerakan Satupun Anggota Gerak', 'Sanggup Gerak 2 Anggota Tubuh', 'Sanggup Gerak 4 Anggota Tubuh')),
  "penilaian_nilai1" smallint,
  "penilaian_skala2" varchar(42) CHECK ("penilaian_skala2" IN ('Apnea Atau Napas Tidak Adekuat', 'Sesak Atau Pernapasan Sedikit Terbatas', 'Sanggup Bernafas Dalam Serta Disuruh Batuk')),
  "penilaian_nilai2" smallint,
  "penilaian_skala3" varchar(38) CHECK ("penilaian_skala3" IN ('± 50% Tekanan Darah Pra Anestesi', '± 20% - 50% Tekanan Darah Pra Anestesi', '± 20% Tekanan Darah Pra Anestesi')),
  "penilaian_nilai3" smallint,
  "penilaian_skala4" varchar(25) CHECK ("penilaian_skala4" IN ('Tidak Ada Respon', 'Respon Terhadap Panggilan', 'Sadar Penuh')),
  "penilaian_nilai4" smallint,
  "penilaian_skala5" varchar(18) CHECK ("penilaian_skala5" IN ('Cianosis', 'Pucat', 'Kemerahan / Normal')),
  "penilaian_nilai5" smallint,
  "penilaian_totalnilai" smallint,
  "keluar" varchar(200),
  "instruksi" varchar(250),
  "kd_dokter" varchar(20) NOT NULL,
  "nip" varchar(20) NOT NULL,
  CONSTRAINT "skor_aldrette_pasca_anestesi_pkey" PRIMARY KEY ("no_rawat", "tanggal")
);

