  "nilai_jam_pertama" smallint,
  "rasa_ingin" varchar(5) CHECK ("rasa_ingin" IN ('Ya', 'Tidak')),
  "nilai_rasa_ingin" smallint,
  "sakit_berat" varchar(5) CHECK ("sakit_berat" IN ('Ya', 'Tidak')),
  "nilai_sakit_berat" smallint,
  "nilai_total" smallint,
  "keterangan_hasil_skrining" varchar(21) CHECK ("keterangan_hasil_skrining" IN ('Ketergantungan Berat', 'Ketergantungan Sedang', 'Ketergantungan Rendah')),
  "skala_motivasi" varchar(113) CHECK ("skala_motivasi" IN ('1. Saya SUDAH memutuskan TIDAK akan berhenti merokok seumur hidup Saya', '2. Saya TIDAK PERNAH berpikir untuk berhenti merokok. Saya TIDAK PUNYA rencana untuk berhenti', '3. Saya PERNAH berpikir untuk berhentl merokok, tetapi Saya TIDAK PUNYA rencana', '4. TERKADANG Saya berpikir untuk berhenti merokok, tetapi Saya tidak punya rencana', '5. Saya SERING berpikir untuk berhentl merokok, tetapi Saya tidak punya rencana', '6. Saya BERENCANA untuk berhenti merokok dalam 6 bulan ke depan', '7. Saya berencana untuk berhenti merokok dalam 30 hari ke depan', '8. Saya masih merokok, tetapi Saya mau berubah. Saya siap untuk berhenti merokok', '9. Saya sudah berhenti merokok, tetapi Saya khawatir akan merokok kembali, Saya butuh lingkungan tanpa asap rokok', '10. Saya sudah berhenti merokok')),
  "nip" varchar(20) NOT NULL,
  CONSTRAINT "skrining_adiksi_nikotin_pkey" PRIMARY KEY ("no_rawat")
);

