  "riwayat_penyakit_keluarga" varchar(31) CHECK ("riwayat_penyakit_keluarga" IN ('Kanker', 'Benjolan Abnormal Pada Payudara', '-')),
  "riwayat_penyakit_sendiri" varchar(31) CHECK ("riwayat_penyakit_sendiri" IN ('Kanker', 'Benjolan Abnormal Pada Payudara', '-')),
