  "risiko_gula_berlebihan" varchar(5) CHECK ("risiko_gula_berlebihan" IN ('Ya', 'Tidak')),
  "risiko_garam_berlebihan" varchar(5) CHECK ("risiko_garam_berlebihan" IN ('Ya', 'Tidak')),
  "risiko_lemak_berlebihan" varchar(5) CHECK ("risiko_lemak_berlebihan" IN ('Ya', 'Tidak')),
  "risiko_kurang_buah_sayur" varchar(5) CHECK ("risiko_kurang_buah_sayur" IN ('Ya', 'Tidak')),
  "risiko_alkohol" varchar(5) CHECK ("risiko_alkohol" IN ('Ya', 'Tidak')),
  "hasil_iva" varchar(13) CHECK ("hasil_iva" IN ('Positif', 'Negatif', 'Curiga Kanker')),
  "hasil_skrining" varchar(50),
  "keterangan" varchar(100) NOT NULL,
  "nip" varchar(20) NOT NULL,
  CONSTRAINT "skrining_risiko_kanker_serviks_pkey" PRIMARY KEY ("no_rawat")
);

-- Tabel skrining_tbc
CREATE TABLE "skrining_tbc" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "berat_badan" varchar(6),
  "tinggi_badan" varchar(8),
  "imt" varchar(6),
  "kasifikasi_imt" varchar(21) CHECK ("kasifikasi_imt" IN ('Berat Badan Kurang', 'Berat Badan Normal', 'Kelebihan Berat Badan', 'Obesitas I', 'Obesitas II')),
  "lingkar_pinggang" varchar(6),
  "risiko_lingkar_pinggang" varchar(9) CHECK ("risiko_lingkar_pinggang" IN ('Rendah', 'Cukup', 'Meningkat', 'Moderat', 'Berat', 'Sangat')),
  "riwayat_kontak_tbc" varchar(5) CHECK ("riwayat_kontak_tbc" IN ('Ya', 'Tidak')),
  "jenis_kontak_tbc" varchar(22) CHECK ("jenis_kontak_tbc" IN ('Tidak', 'TBC Paru Bakteriologis', 'TBC Paru Klinis', 'TBC Paru Ekstraparu')),
  "faktor_resiko_pernah_terdiagnosa_tbc" varchar(5) CHECK ("faktor_resiko_pernah_terdiagnosa_tbc" IN ('Ya', 'Tidak')),
  "keterangan_pernah_terdiagnosa" varchar(40),
  "faktor_resiko_pernah_berobat_tbc" varchar(5) CHECK ("faktor_resiko_pernah_berobat_tbc" IN ('Ya', 'Tidak')),
  "faktor_resiko_malnutrisi" varchar(5) CHECK ("faktor_resiko_malnutrisi" IN ('Ya', 'Tidak')),
  "faktor_resiko_merokok" varchar(5) CHECK ("faktor_resiko_merokok" IN ('Ya', 'Tidak')),
  "faktor_resiko_riwayat_dm" varchar(5) CHECK ("faktor_resiko_riwayat_dm" IN ('Ya', 'Tidak')),
  "faktor_resiko_odhiv" varchar(5) CHECK ("faktor_resiko_odhiv" IN ('Ya', 'Tidak')),
  "faktor_resiko_lansia" varchar(5) CHECK ("faktor_resiko_lansia" IN ('Ya', 'Tidak')),
  "faktor_resiko_ibu_hamil" varchar(5) CHECK ("faktor_resiko_ibu_hamil" IN ('Ya', 'Tidak')),
  "faktor_resiko_wbp" varchar(5) CHECK ("faktor_resiko_wbp" IN ('Ya', 'Tidak')),
  "faktor_resiko_tinggal_diwilayah_padat_kumuh" varchar(5) CHECK ("faktor_resiko_tinggal_diwilayah_padat_kumuh" IN ('Ya', 'Tidak')),
  "abnormalitas_tbc" varchar(22) CHECK ("abnormalitas_tbc" IN ('Normal', 'Abnormalitas TBC', 'Abnormalitas Bukan TBC')),
  "gejala_tbc_batuk" varchar(5) CHECK ("gejala_tbc_batuk" IN ('Ya', 'Tidak')),
  "gejala_tbc_bb_turun" varchar(5) CHECK ("gejala_tbc_bb_turun" IN ('Ya', 'Tidak')),
  "gejala_tbc_demam" varchar(5) CHECK ("gejala_tbc_demam" IN ('Ya', 'Tidak')),
  "gejala_tbc_berkeringat_malam_hari" varchar(5) CHECK ("gejala_tbc_berkeringat_malam_hari" IN ('Ya', 'Tidak')),
  "keterangan_gejala_penyakit_lain" varchar(30),
  "kesimpulan_skrining" varchar(17) CHECK ("kesimpulan_skrining" IN ('Bukan Terduga TBC', 'Kontak Erat', 'Terduga TBC')),
  "keterangan_hasil_skrining" varchar(50),
  "nip" varchar(20) NOT NULL,
  CONSTRAINT "skrining_tbc_pkey" PRIMARY KEY ("no_rawat")
);

-- Tabel skrining_thalassemia
CREATE TABLE "skrining_thalassemia" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "nip" varchar(20) NOT NULL,
  "transfusi_darah" varchar(5) CHECK ("transfusi_darah" IN ('Tidak', 'Ya')),
  "rutin_transfusi" varchar(5) CHECK ("rutin_transfusi" IN ('Tidak', 'Ya')),
  "saudara_thalassemia" varchar(5) CHECK ("saudara_thalassemia" IN ('Tidak', 'Ya')),
  "tumbuh_kembang_terlambat" varchar(5) CHECK ("tumbuh_kembang_terlambat" IN ('Tidak', 'Ya')),
  "anemia" varchar(5) CHECK ("anemia" IN ('Tidak', 'Ya')),
  "ikterus" varchar(5) CHECK ("ikterus" IN ('Tidak', 'Ya')),
  "perut_buncit" varchar(5) CHECK ("perut_buncit" IN ('Tidak', 'Ya')),
  "gizi_kurang" varchar(5) CHECK ("gizi_kurang" IN ('Tidak', 'Ya')),
  "facies_cooley" varchar(5) CHECK ("facies_cooley" IN ('Tidak', 'Ya')),
  "perawakan_pendek" varchar(5) CHECK ("perawakan_pendek" IN ('Tidak', 'Ya')),
  "hiperpigmentasi_kulit" varchar(5) CHECK ("hiperpigmentasi_kulit" IN ('Tidak', 'Ya')),
  "hemoglobin" varchar(10) CHECK ("hemoglobin" IN ('Normal', '< 11 mg/dl')),
  "mvc" varchar(7) CHECK ("mvc" IN ('Normal', '< 80 fl')),
  "mchc" varchar(7) CHECK ("mchc" IN ('Normal', '< 27 pq')),
  "darah_tepi" varchar(13) CHECK ("darah_tepi" IN ('Normal', '< 100.000 mm3')),
  "tindak_lanjut" varchar(300),
  CONSTRAINT "skrining_thalassemia_pkey" PRIMARY KEY ("no_rawat")
);

-- Tabel skrining_tolac
CREATE TABLE "skrining_tolac" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp,
  "gpa" varchar(15),
  "diagnosa" varchar(100),
  "jumlah_sc" varchar(1),
  "tahun_sc" varchar(4),
  "indikasi_sc" varchar(50),
  "jenis_insisi" varchar(18) CHECK ("jenis_insisi" IN ('-', 'Transversal Rendah', 'Klasik', 'Tidak Diketahui')),
  "riwayat_pervaginam" varchar(20) CHECK ("riwayat_pervaginam" IN ('Sebelum & Sesudah SC', 'Sesudah SC Saja', 'Sebelum SC Saja', 'Tidak Pernah')),
  "tbj_gram" varchar(5),
  "presentasi_janin" varchar(30),
  "inklusi_riwayat_sc" varchar(5) CHECK ("inklusi_riwayat_sc" IN ('Ya', 'Tidak')),
  "inklusi_panggul_adekuat" varchar(5) CHECK ("inklusi_panggul_adekuat" IN ('Ya', 'Tidak')),
  "inklusi_janin_tunggal_kepala" varchar(5) CHECK ("inklusi_janin_tunggal_kepala" IN ('Ya', 'Tidak')),
  "inklusi_tbj_sesuai" varchar(5) CHECK ("inklusi_tbj_sesuai" IN ('Ya', 'Tidak')),
  "eksklusi_sc_klasik_ruptur" varchar(5) CHECK ("eksklusi_sc_klasik_ruptur" IN ('Ya', 'Tidak')),
  "eksklusi_sc_2x" varchar(5) CHECK ("eksklusi_sc_2x" IN ('Ya', 'Tidak')),
  "eksklusi_plasenta_previa" varchar(5) CHECK ("eksklusi_plasenta_previa" IN ('Ya', 'Tidak')),
  "kesimpulan" varchar(16) CHECK ("kesimpulan" IN ('Kandidat TOLAC', 'Rujuk SC Elektif')),
  "edukasi_diberikan" varchar(5) CHECK ("edukasi_diberikan" IN ('Ya', 'Tidak')),
  "keterangan" varchar(100) NOT NULL,
  "kd_dokter" varchar(15),
  CONSTRAINT "skrining_tolac_pkey" PRIMARY KEY ("no_rawat")
);

