-- Tabel timeout_sebelum_insisi
CREATE TABLE "timeout_sebelum_insisi" (
  "no_rawat" varchar(17) NOT NULL,
  "tanggal" timestamp NOT NULL,
  "sncn" varchar(25) NOT NULL,
  "tindakan" varchar(50) NOT NULL,
  "kd_dokter_bedah" varchar(20) NOT NULL,
  "kd_dokter_anestesi" varchar(20) NOT NULL,
  "verbal_identitas" varchar(5) CHECK ("verbal_identitas" IN ('Ya', 'Tidak')),
  "verbal_tindakan" varchar(5) CHECK ("verbal_tindakan" IN ('Ya', 'Tidak')),
  "verbal_area_insisi" varchar(5) CHECK ("verbal_area_insisi" IN ('Ya', 'Tidak')),
  "penandaan_area_operasi" varchar(16) CHECK ("penandaan_area_operasi" IN ('Ada', 'Tidak Ada', 'Tidak Diperlukan')),
  "lama_operasi" varchar(10) NOT NULL,
  "penayangan_radiologi" varchar(16) CHECK ("penayangan_radiologi" IN ('Ditayangkan', 'Benar', 'Tidak Diperlukan')),
  "penayangan_ctscan" varchar(16) CHECK ("penayangan_ctscan" IN ('Ditayangkan', 'Benar', 'Tidak Diperlukan')),
  "penayangan_mri" varchar(16) CHECK ("penayangan_mri" IN ('Ditayangkan', 'Benar', 'Tidak Diperlukan')),
  "antibiotik_profilaks" varchar(5) CHECK ("antibiotik_profilaks" IN ('Ya', 'Tidak')),
  "nama_antibiotik" varchar(50) NOT NULL,
  "jam_pemberian" varchar(10) NOT NULL,
  "antisipasi_kehilangan_darah" varchar(50) NOT NULL,
  "hal_khusus" varchar(9) CHECK ("hal_khusus" IN ('Ada', 'Tidak Ada')),
  "hal_khusus_diperhatikan" varchar(100) NOT NULL,
  "tanggal_steril" date,
  "petujuk_sterilisasi" varchar(5) CHECK ("petujuk_sterilisasi" IN ('Ya', 'Tidak')),
  "verifikasi_preoperatif" varchar(5) CHECK ("verifikasi_preoperatif" IN ('Ya', 'Tidak')),
  "nip_perawat_ok" varchar(20),
  CONSTRAINT "timeout_sebelum_insisi_pkey" PRIMARY KEY ("no_rawat", "tanggal")
);

