  "diagnosa_sekunder" varchar(150),
  "indikasi_pindah_ruang" varchar(34) CHECK ("indikasi_pindah_ruang" IN ('Kondisi Pasien Stabil', 'Kondisi Pasien Tidak Ada Perubahan', 'Kondisi Pasien Memburuk', 'Fasilitas Kurang Memadai', 'Fasilitas Butuh Lebih Baik', 'Tenaga Membutuhkan Yang Lebih Ahli', 'Tenaga Kurang', 'Lain-lain')),
  "keterangan_indikasi_pindah_ruang" varchar(100),
  "prosedur_yang_sudah_dilakukan" varchar(800),
  "obat_yang_telah_diberikan" varchar(1200),
  "metode_pemindahan_pasien" varchar(13) CHECK ("metode_pemindahan_pasien" IN ('Kursi Roda', 'Tempat Tidur', 'Brankar', 'Jalan Sendiri', '-')),
  "peralatan_yang_menyertai" varchar(16) CHECK ("peralatan_yang_menyertai" IN ('Oksigen Portable', 'Infus', 'NGT', 'Syringe Pump', 'Suction', 'Kateter Urin', 'Tidak Ada')),
  "keterangan_peralatan_yang_menyertai" varchar(90),
  "pemeriksaan_penunjang_yang_dilakukan" varchar(700),
  "pasien_keluarga_menyetujui" varchar(5) CHECK ("pasien_keluarga_menyetujui" IN ('Ya', 'Tidak')),
  "nama_menyetujui" varchar(50),
  "hubungan_menyetujui" varchar(16) CHECK ("hubungan_menyetujui" IN ('Kakak', 'Adik', 'Saudara', 'Keluarga', 'Kakek', 'Nenek', 'Orang Tua', 'Suami', 'Istri', 'Penanggung Jawab', 'Menantu', 'Ipar', 'Mertua', '-')),
  "keluhan_utama_sebelum_transfer" varchar(300),
  "keadaan_umum_sebelum_transfer" varchar(13) CHECK ("keadaan_umum_sebelum_transfer" IN ('Compos Mentis', 'Gelisah', 'Delirium', 'Koma')),
  "td_sebelum_transfer" varchar(7),
  "nadi_sebelum_transfer" varchar(5),
  "rr_sebelum_transfer" varchar(5),
  "suhu_sebelum_transfer" varchar(5),
  "keluhan_utama_sesudah_transfer" varchar(300),
  "keadaan_umum_sesudah_transfer" varchar(13) CHECK ("keadaan_umum_sesudah_transfer" IN ('Compos Mentis', 'Gelisah', 'Delirium', 'Koma')),
  "td_sesudah_transfer" varchar(7),
  "nadi_sesudah_transfer" varchar(5),
  "rr_sesudah_transfer" varchar(5),
  "suhu_sesudah_transfer" varchar(5),
  "nip_menyerahkan" varchar(20) NOT NULL,
  "nip_menerima" varchar(20) NOT NULL,
  CONSTRAINT "transfer_pasien_antar_ruang_pkey" PRIMARY KEY ("no_rawat", "tanggal_masuk")
);

