-- Tabel utd_cekal_darah
CREATE TABLE "utd_cekal_darah" (
  "no_donor" varchar(15) NOT NULL,
  "tanggal" date,
  "dinas" varchar(5) CHECK ("dinas" IN ('Pagi', 'Siang', 'Sore', 'Malam')),
  "petugas_pemusnahan" varchar(20),
  "keterangan" varchar(100),
  CONSTRAINT "utd_cekal_darah_pkey" PRIMARY KEY ("no_donor")
);

-- Tabel utd_detail_pemisahan_komponen
CREATE TABLE "utd_detail_pemisahan_komponen" (
