  "kode_komponen" varchar(5),
  "tanggal_kadaluarsa" date,
  CONSTRAINT "utd_detail_pemisahan_komponen_pkey" PRIMARY KEY ("no_kantong")
);

-- Tabel utd_donor
CREATE TABLE "utd_donor" (
  "no_donor" varchar(15) NOT NULL,
  "no_pendonor" varchar(15) NOT NULL,
  "tanggal" date,
  "dinas" varchar(5) CHECK ("dinas" IN ('Pagi', 'Siang', 'Sore', 'Malam')),
  "tensi" varchar(7),
  "no_bag" integer,
  "jenis_bag" varchar(2) CHECK ("jenis_bag" IN ('SB', 'DB', 'TB', 'QB')),
  "jenis_donor" varchar(2) CHECK ("jenis_donor" IN ('DB', 'DP', 'DS')),
  "tempat_aftap" varchar(12) CHECK ("tempat_aftap" IN ('Dalam Gedung', 'Luar Gedung')),
  "petugas_aftap" varchar(20),
  "hbsag" varchar(7) CHECK ("hbsag" IN ('Negatif', 'Positif')),
  "hcv" varchar(7) CHECK ("hcv" IN ('Negatif', 'Positif')),
  "hiv" varchar(7) CHECK ("hiv" IN ('Negatif', 'Positif')),
  "spilis" varchar(7) CHECK ("spilis" IN ('Negatif', 'Positif')),
  "malaria" varchar(7) CHECK ("malaria" IN ('Negatif', 'Positif')),
  "petugas_u_saring" varchar(20),
  "status" varchar(5) CHECK ("status" IN ('Aman', 'Cekal')),
  CONSTRAINT "utd_donor_pkey" PRIMARY KEY ("no_donor")
);

